(166,NULL,'EMOTION_EMPATHY','BASIC','EN','KR',3,'I wish','~라면 좋을 텐데','미련이나 아쉬움을 표현하는 I wish','현실과 다른 상황을 바라며 ''~라면 좋을 텐데''라고 아쉬움을 표현합니다. 현재의 아쉬움은 과거형(I wish I had), 과거의 후회는 과거완료형(I wish I had done)을 쓴다는 게 포인트예요.','I have to work this weekend.','나 이번 주말에 일해야 해.','I wish I could go with you.','너랑 같이 갈 수 있으면 좋을 텐데.',ARRAY['I','wish','I','could','go','with','you']::varchar[],ARRAY['you','went','could','go','I','hope','can','with','wish','I']::varchar[],NULL,'[{"sentenceText": "I wish I had more time.", "highlightingPart": "I wish", "sentenceTranslation": "시간이 더 있으면 좋을 텐데.", "practiceQuestion": "Your presentation is due tomorrow, right?", "practiceQuestionTranslation": "너 발표 내일까지 맞지?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/166/practice-examples/f48e621a-5452-4de1-9319-74fe2930d366.webp", "sentenceWords": ["I", "wish", "I", "had", "more", "time"], "sentenceWordChoices": ["wish", "had", "hope", "times", "I", "more", "I", "time", "have"]}, {"sentenceText": "I wish it wasn''t raining.", "highlightingPart": "I wish", "sentenceTranslation": "비가 안 오면 좋을 텐데.", "practiceQuestion": "So much for our picnic plans.", "practiceQuestionTranslation": "소풍 계획은 물 건너갔네.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/166/practice-examples/efac9fa4-9e7f-49b3-b4eb-2b7d6e81b10b.webp", "sentenceWords": ["I", "wish", "it", "wasn''t", "raining"], "sentenceWordChoices": ["hope", "isn''t", "rains", "I", "it", "wasn''t", "raining", "wish"]}, {"sentenceText": "I wish I had studied harder.", "highlightingPart": "I wish", "sentenceTranslation": "공부 더 열심히 할 걸 그랬어.", "practiceQuestion": "How did your exam results turn out?", "practiceQuestionTranslation": "시험 결과 어떻게 나왔어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/166/practice-examples/722f05f9-a549-404f-919b-b6563759eb48.webp", "sentenceWords": ["I", "wish", "I", "had", "studied", "harder"], "sentenceWordChoices": ["studied", "wish", "study", "I", "hope", "harder", "had", "hardly", "I"]}, {"sentenceText": "I wish you lived closer.", "highlightingPart": "I wish", "sentenceTranslation": "네가 더 가까이 살면 좋을 텐데.", "practiceQuestion": "It took me two hours to get to your place.", "practiceQuestionTranslation": "너희 집까지 오는 데 두 시간 걸렸어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/166/practice-examples/24201577-290d-4aa4-ae89-eb8914c58f08.webp", "sentenceWords": ["I", "wish", "you", "lived", "closer"], "sentenceWordChoices": ["closer", "lived", "wish", "I", "hope", "closely", "you", "live"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00873565674,-0.0784912109,-0.0169525146,0.00473022461,0.0156021118,-0.013130188,0.00150203705,0.0227355957,-0.0236663818,-0.010093689,-0.0563354492,0.0336303711,0.000305891037,-0.0313720703,0.0106506348,0.013458252,-0.00579833984,0.0245361328,0.0538024902,-0.0134048462,0.0141296387,-0.0159606934,-0.041809082,0.00777053833,0.0111846924,0.0361633301,0.015914917,-0.0357971191,0.0419921875,0.0124511719,-0.00291442871,-0.0397949219,-0.0177154541,-0.0478210449,0.000838279724,0.0323181152,0.056854248,-0.0187835693,-0.000219106674,-0.0600280762,0.0366821289,-0.0377807617,0.0470581055,-0.0303649902,0.00458526611,0.0524597168,-0.0192565918,-0.0137863159,-0.0159301758,0.00106334686,0.0207366943,0.0118942261,-0.0168762207,0.0642089844,0.0387878418,-0.0247344971,-0.0275726318,-0.0190734863,0.0216827393,-0.0202941895,0.0367431641,0.0156860352,-0.00353431702,0.0527954102,0.0363769531,0.0175170898,0.0212249756,0.0092086792,-0.0200500488,-0.010925293,-0.032043457,-0.0304870605,-0.00964355469,0.0186004639,0.00885009766,-0.0377502441,-0.0232543945,-0.0195007324,0.00537490845,-0.0321960449,0.0156021118,-0.0365600586,-0.0598144531,-0.0549621582,-0.00836181641,-0.0451660156,-0.0410766602,0.00539398193,0.0343017578,-0.00443649292,-0.032623291,-0.0246582031,-0.00127220154,-0.0286254883,0.0194244385,0.0109024048,-0.0374450684,-0.00629043579,-0.0358581543,0.0273895264,0.0301513672,0.014465332,0.0075378418,-