(171,NULL,'EMOTION_EMPATHY','BASIC','EN','KR',8,'I''m glad','~해서 다행이다','다행이라는 마음을 전하는 I''m glad','''~해서 다행이다'', ''~해서 기쁘다''를 자연스럽게 전달하는 표현입니다. glad 뒤에 문장을 바로 붙이면 되고, 상대의 좋은 소식에 공감할 때 특히 많이 써요.','I love the gift you gave me!','네가 준 선물 너무 마음에 들어!','I''m glad you like it.','마음에 든다니 다행이다.',ARRAY['I''m','glad','you','like','it']::varchar[],ARRAY['I''m','happy','glad','you','like','it','likes']::varchar[],NULL,'[{"sentenceText": "I''m glad you made it home safely.", "highlightingPart": "I''m glad", "sentenceTranslation": "무사히 집에 도착했다니 다행이야.", "practiceQuestion": "The typhoon hit right as I was driving back.", "practiceQuestionTranslation": "돌아오는 길에 딱 태풍이 왔었어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/171/practice-examples/82d137df-ab17-4856-b868-e019a03fe2dc.webp", "sentenceWords": ["I''m", "glad", "you", "made", "it", "home", "safely"], "sentenceWordChoices": ["house", "it", "happy", "made", "you", "make", "glad", "safely", "home", "I''m"]}, {"sentenceText": "I''m glad it worked out.", "highlightingPart": "I''m glad", "sentenceTranslation": "잘 풀렸다니 다행이네.", "practiceQuestion": "The deal finally went through.", "practiceQuestionTranslation": "드디어 계약이 성사됐어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/171/practice-examples/f0684e4b-5385-4729-a664-f1d06c6f576e.webp", "sentenceWords": ["I''m", "glad", "it", "worked", "out"], "sentenceWordChoices": ["it", "happy", "worked", "out", "in", "I''m", "glad", "work"]}, {"sentenceText": "I''m glad we finally met.", "highlightingPart": "I''m glad", "sentenceTranslation": "드디어 만나게 돼서 기뻐.", "practiceQuestion": "We''ve only ever talked online until now.", "practiceQuestionTranslation": "우리 지금까지 온라인으로만 얘기했었잖아.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/171/practice-examples/775dfc20-aec2-482f-b290-24dace47e046.webp", "sentenceWords": ["I''m", "glad", "we", "finally", "met"], "sentenceWordChoices": ["glad", "final", "meet", "I''m", "finally", "met", "we", "us"]}, {"sentenceText": "I''m glad to hear that.", "highlightingPart": "I''m glad", "sentenceTranslation": "그 말 들으니 다행이다.", "practiceQuestion": "My test results came back all clear.", "practiceQuestionTranslation": "검사 결과 다 정상으로 나왔어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/171/practice-examples/3f5a137c-47a9-4587-a9f7-b3611d2a61b0.webp", "sentenceWords": ["I''m", "glad", "to", "hear", "that"], "sentenceWordChoices": ["glad", "hear", "happy", "I''m", "that", "hearing", "to"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0464477539,-0.0143051147,-0.0420227051,0.00762557983,0.00704574585,-0.018157959,-0.000970363617,0.0258331299,-0.0164337158,0.0109176636,-0.00996398926,-0.0137939453,0.0106201172,-0.0338439941,1.37686729e-05,0.0331420898,-0.022277832,0.046081543,0.00505828857,0.0391845703,0.0178985596,0.00972747803,-0.0207672119,0.0280914307,-0.00214004517,0.00514984131,-0.0073928833,-0.0014705658,0.0403747559,-0.00214195251,0.0152435303,-0.0174560547,0.0215606689,-0.0550537109,0.0245361328,0.0455322266,-0.0051651001,-0.0207519531,-0.000996589661,-0.054473877,0.024597168,-0.0211639404,0.0283966064,-0.0295410156,0.0166931152,-0.00522613525,-0.0222625732,0.0153198242,0.00761032104,0.0326843262,-0.0327758789,0.0428771973,0.00395965576,0.100891113,0.000255823135,-0.0253143311,0.00172996521,-0.00454330444,0.0228729248,-0.0328674316,0.01612854,0.000181674957,0.0319824219,0.0267791748,0.019744873,-0.0312042236,0.0046005249,-0.00735092163,0.000619888306,-0.00102043152,0.00732803345,0.0112686157,-0.008644104,0.00540924072,-0.0458679199,-0.0132141113,0.039642334,0.0401306152,-0.00639343262,-0.0590820312,-0.0169677734,0.0211334229,-0.014251709,-0.0374145508,-0.0120010376,-0.0514221191,-0.054107666,0.0673217773,0.0166168213,0.0524291992,-0.00813293457,0.0239257812,0.0113143921,-0.00263786316,0.00392150879,-0.018951416,-0.0809326172,0.0335083008,-0.0171966553,0.0135192871,0.0446777344,-0.0076751709,0.0061416626,-0.00315284729,0.0156860352,0.001