(185,NULL,'CONVERSATION_SKILL','BASIC','EN','KR',22,'No wonder','어쩐지, 그럴 만도 하다','판단의 근거를 말하는 No wonder','''어쩐지'', ''그럴 만도 하네''라며 이유를 알고 나서 납득할 때 쓰는 표현입니다. No wonder 뒤에 문장을 붙이면 ''~할 만하다''는 자연스러운 리액션이 돼요.','I only slept two hours last night.','어젯밤 두 시간밖에 못 잤어.','No wonder you''re tired.','어쩐지 피곤하더라니.',ARRAY['No','wonder','you''re','tired']::varchar[],ARRAY['your','wonders','you''re','tiring','tired','wonder','No']::varchar[],NULL,'[{"sentenceText": "No wonder the restaurant is always full.", "highlightingPart": "No wonder", "sentenceTranslation": "어쩐지 그 식당이 항상 만석이더라.", "practiceQuestion": "The chef there trained in Paris for ten years.", "practiceQuestionTranslation": "거기 셰프가 파리에서 10년 수련했대.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/185/practice-examples/cf14ea34-9eb0-40a9-92ae-8a06b79b9689.webp", "sentenceWords": ["No", "wonder", "the", "restaurant", "is", "always", "full"], "sentenceWordChoices": ["wondering", "fully", "the", "restaurant", "wonder", "No", "full", "always", "is", "are"]}, {"sentenceText": "He practices every day. No wonder he''s so good.", "highlightingPart": "No wonder", "sentenceTranslation": "걔 매일 연습하잖아. 잘할 만하지.", "practiceQuestion": "His guitar skills blew me away yesterday.", "practiceQuestionTranslation": "어제 걔 기타 실력 보고 완전 놀랐잖아.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/185/practice-examples/b4e741eb-3b70-490e-8db2-87a0514ab1fd.webp", "sentenceWords": ["He", "practices", "every", "day", "No", "wonder", "he''s", "so", "good"], "sentenceWordChoices": ["He", "day", "wonders", "so", "he''s", "wonder", "practices", "No", "every", "practice", "well", "good"]}, {"sentenceText": "No wonder it was so cheap.", "highlightingPart": "No wonder", "sentenceTranslation": "어쩐지 그렇게 싸더라니.", "practiceQuestion": "Turns out that jacket was a factory second.", "practiceQuestionTranslation": "알고 보니 그 재킷 B급 상품이었대.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/185/practice-examples/637bbf12-26e9-4790-b54d-0c4a5707b067.webp", "sentenceWords": ["No", "wonder", "it", "was", "so", "cheap"], "sentenceWordChoices": ["were", "cheaply", "No", "so", "it", "wondered", "wonder", "cheap", "was"]}, {"sentenceText": "No wonder she was upset.", "highlightingPart": "No wonder", "sentenceTranslation": "걔가 화날 만도 했네.", "practiceQuestion": "Apparently nobody told her the plan had changed.", "practiceQuestionTranslation": "계획 바뀐 걸 아무도 걔한테 말 안 해줬대.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/185/practice-examples/2764b5ec-473d-4635-91bc-e8833357d945.webp", "sentenceWords": ["No", "wonder", "she", "was", "upset"], "sentenceWordChoices": ["No", "upset", "upsetting", "wonders", "was", "wonder", "her", "she"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0037651062,-0.0178222656,-0.0501708984,0.037109375,0.0100097656,-0.0123214722,-0.0464172363,-0.00434494019,-0.0272521973,0.0086517334,-0.0190887451,0.0123519897,0.000277757645,0.0223083496,0.000919818878,-0.0104751587,-0.0408630371,-0.00481796265,0.0485839844,0.0222930908,0.00321388245,0.0303649902,-0.0237731934,-0.0103683472,0.0187683105,-0.0123519897,-0.0195922852,0.00611877441,0.0259094238,0.00867462158,0.0291748047,-0.0124893188,-0.00659942627,-0.0767822266,0.0432128906,0.071472168,0.023651123,-0.0648803711,-0.0266418457,-0.0276794434,0.035949707,-0.0411376953,0.0202941895,0.00273895264,0.0364990234,0.0272064209,0.00442886353,0.0338439941,0.0123901367,-0.00108718872,-0.0299987793,0.0778198242,0.0301971436,0.078125,-0.0157165527,-0.0411682129,0.0169830322,0.0243988037,-0.00699234009,-0.0592041016,0.0230865479,0.0116500854,0.013381958,0.0684204102,0.00710678101,0.0216674805,0.0570068359,0.00518798828,-0.0220794678,0.0332946777,-0.0094833374,0.00190830231,-0.029876709,0.00931549072,-0.0103759766,-0.00555419922,0.0234069824,0.00954437256,0.019317627,-0.0222320557,0.0344238281,0.024887085,-0.0255432129,-0.00650405884,-0.0177154541,-0.0377502441,-0.0430908203,0.0243988037,-0.0217285156,-0.013