(197,NULL,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',34,'that (주어로 쓰기)','앞의 상황·행동을 that으로 받기','지시대명사 that을 주어로 쓰기','앞에 나온 행동이나 상황 전체를 that으로 받아 주어로 쓰는 방식입니다. That didn''t help(그게 도움이 안 됐어)처럼 문장을 간결하고 원어민스럽게 만들어줘요.','Did the apology work?','사과가 통했어?','I apologized, but that didn''t help.','사과했는데 그게 소용이 없었어.',ARRAY['I','apologized','but','that','didn''t','help']::varchar[],ARRAY['helped','I','didn''t','help','doesn''t','apologized','but','this','that']::varchar[],NULL,'[{"sentenceText": "I drank some coffee, but that didn''t wake me up.", "highlightingPart": "that", "sentenceTranslation": "커피를 마셨는데도 잠이 안 깼어.", "practiceQuestion": "You look half asleep. Are you okay?", "practiceQuestionTranslation": "너 반쯤 조는 것 같은데, 괜찮아?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/197/practice-examples/5ffb5008-2557-41e7-8cf5-5ec0bac4bd8d.webp", "sentenceWords": ["I", "drank", "some", "coffee", "but", "that", "didn''t", "wake", "me", "up"], "sentenceWordChoices": ["coffee", "up", "didn''t", "me", "drank", "that", "drunk", "this", "wake", "woke", "some", "but", "I"]}, {"sentenceText": "We tried restarting it, but that didn''t work.", "highlightingPart": "that", "sentenceTranslation": "재부팅해 봤는데 그걸로는 안 되더라.", "practiceQuestion": "Is the Wi-Fi still down?", "practiceQuestionTranslation": "와이파이 아직도 안 돼?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/197/practice-examples/11277352-08cd-49dd-b8c5-0622b1d12a16.webp", "sentenceWords": ["We", "tried", "restarting", "it", "but", "that", "didn''t", "work"], "sentenceWordChoices": ["it", "didn''t", "doesn''t", "that", "restarting", "this", "We", "worked", "tried", "work", "but"]}, {"sentenceText": "That changed everything.", "highlightingPart": "That", "sentenceTranslation": "그게 모든 걸 바꿔놨어.", "practiceQuestion": "What happened after the new coach came in?", "practiceQuestionTranslation": "새 코치 오고 나서 어떻게 됐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/197/practice-examples/e3cf317c-2147-4c66-a9e7-6fb35d62bdd9.webp", "sentenceWords": ["That", "changed", "everything"], "sentenceWordChoices": ["everything", "changes", "That", "This", "anything", "changed"]}, {"sentenceText": "That made my day.", "highlightingPart": "That", "sentenceTranslation": "그것 덕분에 기분 최고였어.", "practiceQuestion": "Did you see the thank-you note your student left?", "practiceQuestionTranslation": "네 학생이 남긴 감사 쪽지 봤어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/197/practice-examples/e643f059-f9a4-4c9e-87dc-69cd4564896a.webp", "sentenceWords": ["That", "made", "my", "day"], "sentenceWordChoices": ["day", "made", "makes", "That", "This", "my"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00538253784,-0.00800323486,-0.0521850586,0.0215759277,0.0205993652,-0.0254364014,-0.0409240723,-0.0219573975,0.0335998535,-0.0476989746,-0.0151672363,0.0179748535,-0.0126571655,-0.0538024902,-0.0200805664,-0.0334472656,-0.0819702148,0.0324707031,0.0643310547,-0.0151901245,0.00349617004,0.0106201172,0.0047416687,0.0281524658,0.0264892578,0.00341415405,-0.00135707855,0.0217132568,0.0477905273,-0.0188751221,-0.0338439941,-0.024887085,0.0303344727,-0.0717163086,-0.000352144241,0.0134048462,0.0141677856,-0.0194091797,0.00437927246,-0.00247383118,0.0177154541,-0.0669555664,0.0163879395,0.00729370117,0.0345458984,0.0397033691,-0.0148696899,0.0234069824,-0.0228881836,0.0206756592,0.0229034424,0.00855255127,-0.0177764893,0.0143737793,-0.000124812126,-0.0569763184,0.00721359253,0.0437011719,0.00468444824,-0.0215759277,0.0281066895,-0.0272979736,0.00520324707,0.0376281738,0.00961303711,-0.00444030762,0.0109176636,0.0918579102,-0.017364502,0.0175170898,0.00629043579,-0.00679397583,-0.00109481812,-0.0139465332,0.0163269043,-0.0116882324,-0.0505371094,0.0473632812,-0.00572967529,-0.0216674805,-0.00377082825,-0.0204467773,-0.0154037476,-0.0311737061,-0.00637054443,-0.00955200195,-0.0354003906,0.0466003418,0.0413818359,-0.0255432129,0.0406494141,0.0257568359,-0.00555419