(203,NULL,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',40,'when','~할 때(마다)','조건과 상황을 잇는 when','접속사 when은 ''~할 때(마다)''라며 조건과 그에 따른 상황을 자연스럽게 연결합니다. 반복되는 패턴이나 일반적 사실을 말할 때 if보다 자연스러운 경우가 많아요.','Why do you get so sleepy?','넌 왜 그렇게 졸려?','I get sleepy when I eat too much.','난 과식하면 졸려.',ARRAY['I','get','sleepy','when','I','eat','too','much']::varchar[],ARRAY['gets','much','too','many','sleepy','get','I','eats','I','eat','when']::varchar[],NULL,'[{"sentenceText": "Call me when you get home.", "highlightingPart": "when", "sentenceTranslation": "집에 도착하면 전화해.", "practiceQuestion": "I''m heading out now. See you tomorrow!", "practiceQuestionTranslation": "나 이제 갈게. 내일 봐!", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/203/practice-examples/d715cd40-b05d-41df-b916-5c1cafe3cb8f.webp", "sentenceWords": ["Call", "me", "when", "you", "get", "home"], "sentenceWordChoices": ["when", "home", "get", "gets", "Calls", "my", "you", "me", "Call"]}, {"sentenceText": "The roads get slippery when it snows.", "highlightingPart": "when", "sentenceTranslation": "눈이 오면 길이 미끄러워져.", "practiceQuestion": "Why do you drive so slowly in winter?", "practiceQuestionTranslation": "겨울엔 왜 그렇게 천천히 운전해?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/203/practice-examples/1b605063-7eaa-4ca4-8657-83afb4be7dd4.webp", "sentenceWords": ["The", "roads", "get", "slippery", "when", "it", "snows"], "sentenceWordChoices": ["snowing", "when", "slip", "snows", "it", "gets", "The", "slippery", "get", "roads"]}, {"sentenceText": "I listen to music when I cook.", "highlightingPart": "when", "sentenceTranslation": "난 요리할 때 음악을 들어.", "practiceQuestion": "I always hear music coming from your kitchen.", "practiceQuestionTranslation": "너네 부엌에서 맨날 음악 소리 들리더라.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/203/practice-examples/ef8b5287-578d-4f4e-b7ed-b7c7d7eb245c.webp", "sentenceWords": ["I", "listen", "to", "music", "when", "I", "cook"], "sentenceWordChoices": ["to", "cooks", "music", "listen", "cook", "I", "I", "when", "listens"]}, {"sentenceText": "My knees hurt when it''s cold.", "highlightingPart": "when", "sentenceTranslation": "날이 추우면 무릎이 아파.", "practiceQuestion": "Why do you hate winter so much?", "practiceQuestionTranslation": "넌 왜 그렇게 겨울을 싫어해?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/203/practice-examples/3083fd02-748a-4668-97ef-d55668ea26eb.webp", "sentenceWords": ["My", "knees", "hurt", "when", "it''s", "cold"], "sentenceWordChoices": ["hurts", "hurt", "cold", "when", "My", "knees", "it''s", "coldly"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0031414032,-0.0184326172,-0.0438232422,0.0295562744,0.0354919434,-0.00597381592,0.0260314941,0.0110778809,-0.0188751221,0.0167236328,0.00366973877,0.0121154785,-0.00317764282,-0.0092010498,0.024520874,0.0422363281,-0.0453491211,0.0156173706,0.0114364624,0.0308990479,0.0135345459,-0.0149002075,0.00380706787,0.046661377,-0.0144348145,-0.0127258301,0.0259857178,0.0525512695,0.0311584473,0.0265197754,0.0261535645,-0.0304107666,0.0146942139,-0.0348510742,0.0392150879,0.0321655273,0.0169219971,0.0255584717,0.00821685791,-0.0181732178,0.0161590576,-0.020401001,-0.0015630722,0.0278778076,0.0439758301,0.00790405273,-0.00741958618,-0.00219917297,0.0178070068,0.0162658691,-0.000255346298,0.00421905518,-0.00403594971,0.0284881592,0.0174865723,-0.0149154663,-0.00379562378,0.0118484497,0.0447998047,-0.0134887695,0.028137207,-0.0364685059,0.000127911568,0.0397033691,-0.0254669189,-0.0272521973,0.0487670898,-0.0161895752,-0.0175476074,-0.0261993408,0.052947998,0.0180511475,0.0130386353,0.0197906494,-0.0143127441,-0.00859069824,-0.0166168213,0.00200653076,0.0418701172,-0.00947570801,0.0233764648,-0.0228881836,-0.0381164551,-0.0362854004,-0.0120162964,-0.0716552734,-0.0536499023,0.0480041504,-0.0338745117,-0.00800323486,0.0333251953,0.0668334961,0.0341491699,-0.01197052,-0.00194454193,0.0422668457,-0.0103759766,0.0375366211,-0.017364502,0.0329284668,