(218,NULL,'EMOTION_EMPATHY','BASIC','EN','KR',55,'pick ~ up','기운 나게 하다','기운을 북돋는 pick ~ up','''기분을 북돋다, 기운 나게 하다''라는 뜻입니다. That picks me up이라고 하면 ''그게 날 기운 나게 해''라는 의미로, pick-me-up(기운 나게 하는 것)이라는 명사로도 쓰여요.','How do you cheer yourself up?','넌 어떻게 기분을 풀어?','A good song always picks me up.','좋은 노래는 언제나 날 기운 나게 해.',ARRAY['A','good','song','always','picks','me','up']::varchar[],ARRAY['up','songs','pick','song','me','always','A','good','picks','my']::varchar[],NULL,'[{"sentenceText": "Your message really picked me up.", "highlightingPart": "picked me up", "sentenceTranslation": "네 메시지 덕분에 진짜 힘이 났어.", "practiceQuestion": "I heard you had a rough day yesterday.", "practiceQuestionTranslation": "너 어제 힘든 하루였다며.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/218/practice-examples/0103303e-d824-4e4f-aa3b-cbd9c1852c80.webp", "sentenceWords": ["Your", "message", "really", "picked", "me", "up"], "sentenceWordChoices": ["picks", "really", "my", "picked", "Your", "message", "me", "up", "messages"]}, {"sentenceText": "Coffee picks me up in the morning.", "highlightingPart": "picks me up", "sentenceTranslation": "아침엔 커피가 날 깨워줘.", "practiceQuestion": "How do you wake yourself up before work?", "practiceQuestionTranslation": "출근 전에 잠은 어떻게 깨?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/218/practice-examples/007dfee7-4585-4c30-8f73-3b4bc9170259.webp", "sentenceWords": ["Coffee", "picks", "me", "up", "in", "the", "morning"], "sentenceWordChoices": ["pick", "in", "evening", "up", "me", "morning", "picks", "Coffee", "the", "my"]}, {"sentenceText": "Nothing picks me up like a walk in the sun.", "highlightingPart": "picks me up", "sentenceTranslation": "햇볕 쬐며 걷는 것만큼 기운 나는 게 없어.", "practiceQuestion": "The weather is gorgeous today.", "practiceQuestionTranslation": "오늘 날씨 진짜 좋다.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/218/practice-examples/03aa7521-0cf4-434a-8e94-1a90c910e076.webp", "sentenceWords": ["Nothing", "picks", "me", "up", "like", "a", "walk", "in", "the", "sun"], "sentenceWordChoices": ["picks", "the", "a", "in", "me", "Anything", "sun", "walks", "up", "walk", "Nothing", "like", "pick"]}, {"sentenceText": "I need a little pick-me-up today.", "highlightingPart": "pick-me-up", "sentenceTranslation": "오늘은 기운 낼 뭔가가 필요해.", "practiceQuestion": "You look drained. Rough morning?", "practiceQuestionTranslation": "너 완전 지쳐 보여. 아침부터 힘들었어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/218/practice-examples/e7a9edfb-aca4-4318-9207-de3acb9a5997.webp", "sentenceWords": ["I", "need", "a", "little", "pick-me-up", "today"], "sentenceWordChoices": ["needs", "today", "pick-me-up", "tonight", "I", "little", "need", "a"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0126953125,-0.0317687988,-0.0537109375,-0.0207824707,-0.00901794434,-0.00722885132,-0.0304260254,0.0492858887,0.000261545181,0.0120620728,-0.00591278076,0.0204925537,0.00108337402,0.0100402832,0.0181121826,0.0171508789,-0.0109024048,-0.0441894531,-0.0560913086,0.00854492188,0.0265045166,0.0309295654,0.0431518555,0.018737793,0.00252723694,0.0253753662,0.00511550903,0.0393371582,-0.00223350525,-0.0349731445,-0.0524291992,-0.0298919678,-0.0241394043,-0.0759887695,0.0146255493,-0.0276947021,-0.0015296936,0.0272674561,-0.0446166992,-0.00645828247,0.017868042,-0.0567626953,0.0270233154,-0.0111618042,0.042755127,0.0298461914,0.00283050537,-0.0423583984,0.0347900391,0.0166320801,-0.0224609375,-0.000515460968,-0.0148696899,0.0280914307,0.00199890137,-0.0131912231,0.0322570801,-0.00812530518,0.0305480957,-0.0230712891,0.00448226929,-0.0411376953,0.0210723877,0.0428161621,0.016784668,0.00287055969,0.00164031982,-0.00463104248,-0.0222320557,0.0254669189,0.00852203369,-0.0216522217,-0.00863647461,-0.0224456787,0.0266876221,0.0416870117,-0.030090332,-0.0257873535,-0.0261688232,0.0147628784,0.0259246826,-0.0824584961,-0.0195922852,-0.0389099121,-0.0238647461,-0.0967407227,-0.0173492432,0.00443267822,0.048553