(228,NULL,'DAILY_ROUTINE','BASIC','EN','KR',65,'plug in','플러그를 꽂다','플러그를 꽂는 plug in','''플러그를 꽂다, 전원을 연결하다''라는 뜻입니다. 반대는 unplug(플러그를 뽑다)로, 전자기기 일상 대화의 기본 표현이에요.','Why won''t my phone turn on?','폰이 왜 안 켜져?','Is the charger plugged in?','충전기 꽂혀 있어?',ARRAY['Is','the','charger','plugged','in']::varchar[],ARRAY['Is','charger','in','plug','Are','on','the','plugged']::varchar[],NULL,'[{"sentenceText": "Plug in your phone before bed.", "highlightingPart": "Plug in", "sentenceTranslation": "자기 전에 폰 충전기 꽂아놔.", "practiceQuestion": "My alarm didn''t go off because my phone died again.", "practiceQuestionTranslation": "폰이 또 꺼져서 알람이 안 울렸어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/228/practice-examples/12fdc27c-b58c-4b09-bc03-7e3010dcb9c8.webp", "sentenceWords": ["Plug", "in", "your", "phone", "before", "bed"], "sentenceWordChoices": ["Plugs", "in", "Plug", "after", "before", "bed", "your", "yours", "phone"]}, {"sentenceText": "Where can I plug in my laptop?", "highlightingPart": "plug in", "sentenceTranslation": "노트북 어디에 꽂을 수 있어요?", "practiceQuestion": "Welcome! Feel free to sit anywhere.", "practiceQuestionTranslation": "어서 오세요! 편한 자리에 앉으세요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/228/practice-examples/d52dcd3d-16ea-4cb5-ac5a-ca5d590dd46d.webp", "sentenceWords": ["Where", "can", "I", "plug", "in", "my", "laptop"], "sentenceWordChoices": ["I", "me", "plug", "Where", "laptop", "in", "plugs", "can", "When", "my"]}, {"sentenceText": "The TV isn''t working because it''s not plugged in.", "highlightingPart": "plugged in", "sentenceTranslation": "TV가 안 되는 건 플러그가 안 꽂혀서야.", "practiceQuestion": "I keep pressing the remote, but nothing happens.", "practiceQuestionTranslation": "리모컨 아무리 눌러도 반응이 없어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/228/practice-examples/4bf0676e-9b88-482f-9f82-d7de7a680f74.webp", "sentenceWords": ["The", "TV", "isn''t", "working", "because", "it''s", "not", "plugged", "in"], "sentenceWordChoices": ["works", "TV", "its", "working", "plug", "because", "it''s", "plugged", "in", "isn''t", "The", "not"]}, {"sentenceText": "I forgot to plug in the vacuum.", "highlightingPart": "plug in", "sentenceTranslation": "청소기 플러그 꽂는 걸 깜빡했어.", "practiceQuestion": "I thought you were going to vacuum today.", "practiceQuestionTranslation": "오늘 청소기 돌린다며.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/228/practice-examples/eaf56aab-9793-4a05-9a49-2e06e0e0abcd.webp", "sentenceWords": ["I", "forgot", "to", "plug", "in", "the", "vacuum"], "sentenceWordChoices": ["vacuums", "vacuum", "I", "forget", "to", "in", "plug", "forgot", "plugging", "the"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00189590454,-0.0161743164,-0.0837402344,-0.0296173096,0.0141677856,-0.0304107666,0.00113391876,0.0340881348,-0.00227737427,0.0003054142,0.0316162109,0.0181884766,0.0359802246,0.00178337097,-0.0113449097,0.00804901123,-0.0328369141,-0.0298156738,0.0256195068,0.0311737061,0.0313415527,-0.0062713623,0.0417480469,0.0389404297,-0.00915527344,0.0359802246,-0.0384216309,0.0561218262,-0.00629043579,-0.02734375,-0.00434112549,-0.0354003906,0.0420532227,-0.0156021118,0.0400695801,-0.00793457031,0.0139541626,-0.00556945801,0.0167999268,-0.0214385986,-0.000762462616,-0.0571289062,0.0320129395,0.0472106934,0.00299453735,0.0267791748,-0.0584106445,0.00063085556,0.045135498,0.015007019,-0.0308837891,0.0161743164,0.00119686127,0.031829834,-0.033416748,0.0204620361,-0.013923645,0.00392913818,-0.00689697266,-0.0504760742,0.00874328613,0.0129852295,0.0342712402,0.0458679199,-0.0149307251,0.0240631104,-0.0313110352,-0.00326347351,-0.0297393799,0.0220947266,0.0243988037,0.00111865997,-0.0833740234,0.0107650757,0.0154037476,0.0257873535,-0.0179901123,0.048828125,0.0182800293,-0.0276947021,0.02734375,-0.0329284668,-0.000333786011,-0.0598449707,-0.0422668457,-0.0524597168,-0.0631713867,-0.0286865234,-0.020980835,-0.0579528809,0.00879669189,0.0546875,0.00472640991,0.030