(230,NULL,'RELATIONSHIP_SOCIAL','BASIC','EN','KR',67,'see ~ off','~를 배웅하다','배웅하는 see ~ off','''~를 배웅하다''라는 뜻으로, 떠나는 사람을 출발 지점까지 바래다주는 것을 말합니다. 공항, 역 등 이별 장면의 단골 표현이에요.','Where were you this morning?','오늘 아침에 어디 있었어?','We went to the station to see her off.','걔 배웅하러 역에 갔어.',ARRAY['We','went','to','the','station','to','see','her','off']::varchar[],ARRAY['saw','her','to','went','off','the','We','station','goes','to','hers','see']::varchar[],NULL,'[{"sentenceText": "My whole family came to see me off.", "highlightingPart": "see me off", "sentenceTranslation": "온 가족이 날 배웅하러 나왔어.", "practiceQuestion": "Weren''t you lonely leaving the country alone?", "practiceQuestionTranslation": "혼자 출국하는데 안 외로웠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/230/practice-examples/4f2ca927-6c14-4a23-9f3a-89b3266fb30d.webp", "sentenceWords": ["My", "whole", "family", "came", "to", "see", "me", "off"], "sentenceWordChoices": ["come", "I", "to", "see", "whole", "came", "sees", "My", "family", "off", "me"]}, {"sentenceText": "Thanks for seeing me off.", "highlightingPart": "seeing me off", "sentenceTranslation": "배웅해 줘서 고마워.", "practiceQuestion": "Have a safe trip! Text me when you land.", "practiceQuestionTranslation": "조심히 가! 도착하면 연락해.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/230/practice-examples/36431fe5-927f-4363-899c-6dad322a2dfb.webp", "sentenceWords": ["Thanks", "for", "seeing", "me", "off"], "sentenceWordChoices": ["my", "seeing", "me", "see", "for", "Thanks", "Thank", "off"]}, {"sentenceText": "He saw his parents off at the gate.", "highlightingPart": "saw his parents off", "sentenceTranslation": "걔는 게이트에서 부모님을 배웅했어.", "practiceQuestion": "Did his parents leave for their trip okay?", "practiceQuestionTranslation": "걔네 부모님 여행 잘 떠나셨대?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/230/practice-examples/8d8de9e7-7db8-4ee1-9dcd-17fcc25cfb83.webp", "sentenceWords": ["He", "saw", "his", "parents", "off", "at", "the", "gate"], "sentenceWordChoices": ["He", "his", "him", "on", "saw", "gate", "off", "parents", "seen", "the", "at"]}, {"sentenceText": "I''ll see you off at the bus stop.", "highlightingPart": "see you off", "sentenceTranslation": "버스 정류장까지 배웅해 줄게.", "practiceQuestion": "It''s late. I should get going now.", "practiceQuestionTranslation": "늦었다. 나 이제 가봐야겠어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/230/practice-examples/906304ff-5b62-473c-a6fe-c574b7e986f6.webp", "sentenceWords": ["I''ll", "see", "you", "off", "at", "the", "bus", "stop"], "sentenceWordChoices": ["stops", "sees", "see", "you", "bus", "at", "stop", "off", "the", "I''ll", "your"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0359191895,0.0400695801,-0.0431213379,0.00860595703,-0.0629272461,-0.0126876831,0.00495147705,-0.0152130127,0.0294342041,0.0397644043,0.0381774902,-0.0207214355,0.00327301025,0.00195884705,0.0127792358,0.00839233398,-0.0155258179,0.0340576172,0.0513305664,0.0646972656,0.0255584717,-0.00157928467,-0.0122146606,0.067199707,-0.0251464844,0.00687408447,0.0064163208,0.000541210175,0.0319213867,-0.00263786316,0.00971984863,-0.0332336426,0.0263824463,-0.0690307617,0.00688552856,0.00817108154,0.0299530029,-0.0480041504,-0.0118713379,-0.0270233154,-0.0195159912,-0.0448303223,0.0160064697,-0.056854248,0.0554504395,0.0614013672,0.00608062744,0.0520019531,0.0180206299,-0.000514030457,0.0221405029,0.02003479,-0.00397491455,0.0404968262,-0.00582122803,-0.0238037109,-0.000158548355,0.0203094482,0.0311431885,-0.00897979736,0.0375061035,0.00666809082,0.0211791992,0.0740966797,-0.0264129639,-0.0421142578,0.0094909668,0.0101394653,-0.00861358643,0.0504760742,-0.00516891479,-0.0220031738,-0.0212554932,0.018157959,0.0273590088,-0.0202026367,0.0354614258,0.015045166,0.00969696045,-0.017364502,0.0412597656,-0.0350341797,-0.0385131836,0.0234222412,0.0040435791,-0.042175293,-0.0424804688,0.0294952393,0.01612854,0.0360412598,0.0236968994,0.0524597168,-0.00486755371,