(237,NULL,'CONVERSATION_SKILL','BASIC','EN','KR',74,'hold on','잠깐 기다리다','잠깐 기다려 달라는 hold on','''잠깐 기다리다''라는 뜻으로, 통화나 대화 중 잠시 멈춰달라고 할 때 씁니다. Hold on a second/minute처럼 시간 표현과 함께 자주 쓰여요.','Can you help me for a second?','잠깐만 도와줄 수 있어?','Hold on, I''ll be right back.','잠깐만, 금방 올게.',ARRAY['Hold','on','I''ll','be','right','back']::varchar[],ARRAY['I''ll','being','backs','Holds','back','on','be','Hold','right']::varchar[],NULL,'[{"sentenceText": "Hold on a minute, let me check.", "highlightingPart": "Hold on", "sentenceTranslation": "잠깐만요, 확인해 볼게요.", "practiceQuestion": "Do you have this in a size medium?", "practiceQuestionTranslation": "이거 미디엄 사이즈 있나요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/237/practice-examples/963bc811-0252-4915-bde0-2985dceb7a1c.webp", "sentenceWords": ["Hold", "on", "a", "minute", "let", "me", "check"], "sentenceWordChoices": ["minute", "Holds", "me", "on", "minutes", "checks", "Hold", "let", "a", "check"]}, {"sentenceText": "Hold on, are you serious?", "highlightingPart": "Hold on", "sentenceTranslation": "잠깐, 진심이야?", "practiceQuestion": "I''m quitting my job to travel the world.", "practiceQuestionTranslation": "나 회사 그만두고 세계여행 갈 거야.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/237/practice-examples/d5644633-4f07-476a-812e-667e75fd034a.webp", "sentenceWords": ["Hold", "on", "are", "you", "serious"], "sentenceWordChoices": ["are", "serious", "is", "you", "Hold", "seriously", "Holds", "on"]}, {"sentenceText": "Can you hold on while I grab a pen?", "highlightingPart": "hold on", "sentenceTranslation": "펜 좀 가져올 동안 잠깐 기다려 줄래요?", "practiceQuestion": "I''d like to leave a message for Mr. Teddy.", "practiceQuestionTranslation": "테디 선생님께 메시지 좀 남기고 싶은데요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/237/practice-examples/787c4251-10d2-41dc-8777-abcc738bf802.webp", "sentenceWords": ["Can", "you", "hold", "on", "while", "I", "grab", "a", "pen"], "sentenceWordChoices": ["Can", "hold", "pens", "I", "pen", "while", "you", "grab", "a", "holds", "grabs", "on"]}, {"sentenceText": "Hold on tight!", "highlightingPart": "Hold on", "sentenceTranslation": "꽉 잡아!", "practiceQuestion": "Is it okay if I ride on the back?", "practiceQuestionTranslation": "뒤에 타도 돼?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/237/practice-examples/1e1c8db8-f78e-4843-94d3-eea5a52eebdd.webp", "sentenceWords": ["Hold", "on", "tight"], "sentenceWordChoices": ["tights", "Holds", "tight", "Hold", "on"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0400390625,-0.0145187378,-0.0595397949,-0.0321350098,-0.047088623,-0.01902771,-0.00400161743,0.0107345581,-0.0162811279,0.013633728,-0.00290107727,-0.0122680664,0.0125198364,-0.0424194336,-0.039642334,0.01222229,-0.0300140381,0.0236053467,0.0229644775,0.0369873047,-0.067199707,-0.0144271851,0.0242156982,0.0223388672,0.00456619263,0.0129852295,0.023727417,0.0104751587,0.0403442383,-0.00705718994,0.0154876709,-0.0266571045,-0.000166416168,-0.0241546631,0.00349235535,0.040222168,0.0245513916,-0.032043457,-0.0423278809,-0.0519714355,0.0133743286,-0.0546264648,0.0678710938,-0.0529174805,0.0704956055,0.0536193848,0.0192871094,-0.0179748535,0.0254669189,0.0503234863,0.0313720703,0.0393676758,-0.0221405029,0.0643310547,0.0215606689,-0.0320739746,-0.0153884888,0.0324707031,0.0539855957,-0.0178070068,-0.0121536255,-0.0467834473,0.00631332397,0.0285186768,0.032043457,-0.0153808594,0.0130004883,0.021194458,-0.0337524414,0.0283660889,0.00221443176,-0.0242156982,-0.0146713257,0.000165343285,-0.0287017822,0.0474853516,0.0311584473,0.0325622559,0.0186920166,-0.00622177124,0.0309143066,-0.0615539551,-0.0198516846,0.00458526611,-0.0137405396,-0.0290374756,-0.0970458984,0.0342407227,0.032989502,-0.00150680542,0.0297546387,0.0444335938,0.00734329224,0.0311889648,-0.0129852295,-0.0307159424,-0.00378227234,0.0422668457,-0.0348205566,-0.00452804565,0.0336608887,-0.0370178223,-0.000313520432,-0.0379638672,0.029296875,0.02040