(242,NULL,'WORK_STUDY','BASIC','EN','KR',79,'snowed under','(일에) 파묻히다','일이 산더미일 때 snowed under','''(일에) 파묻히다''라는 뜻으로, 눈에 파묻힌 모습에 빗댄 표현입니다. be snowed under with work라고 하면 일이 감당 안 될 만큼 쌓였다는 의미예요.','Want to grab dinner tonight?','오늘 밤 저녁 먹을래?','I''m totally snowed under this week.','이번 주 일이 완전 산더미야.',ARRAY['I''m','totally','snowed','under','this','week']::varchar[],ARRAY['snowed','this','snow','over','totally','I''m','under','weeks','week']::varchar[],NULL,'[{"sentenceText": "She''s snowed under with assignments.", "highlightingPart": "snowed under", "sentenceTranslation": "걔 과제에 파묻혀 있어.", "practiceQuestion": "Why hasn''t she been at the gym lately?", "practiceQuestionTranslation": "걔 요즘 왜 헬스장에 안 나와?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/242/practice-examples/e3c0d468-538d-4fa3-a98e-9062be95fa8e.webp", "sentenceWords": ["She''s", "snowed", "under", "with", "assignments"], "sentenceWordChoices": ["over", "snowed", "snows", "with", "assignment", "under", "She''s", "assignments"]}, {"sentenceText": "Sorry, I can''t make it. I''m snowed under at work.", "highlightingPart": "snowed under", "sentenceTranslation": "미안, 못 가. 회사 일이 산더미야.", "practiceQuestion": "We''re all getting together this Friday. You in?", "practiceQuestionTranslation": "이번 금요일에 다 같이 모이기로 했어. 너도 올 거지?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/242/practice-examples/c57fa60b-1fce-4752-ba1f-539e7aeebb04.webp", "sentenceWords": ["Sorry", "I", "can''t", "make", "it", "I''m", "snowed", "under", "at", "work"], "sentenceWordChoices": ["can''t", "works", "I''m", "snowed", "makes", "Sorry", "work", "make", "it", "snow", "I", "at", "under"]}, {"sentenceText": "We''re snowed under with orders right now.", "highlightingPart": "snowed under", "sentenceTranslation": "지금 주문이 밀려서 정신이 없어.", "practiceQuestion": "How''s business at the shop these days?", "practiceQuestionTranslation": "요즘 가게 장사 어때?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/242/practice-examples/7d4d4af7-0c5b-4ad1-b19d-d01399500684.webp", "sentenceWords": ["We''re", "snowed", "under", "with", "orders", "right", "now"], "sentenceWordChoices": ["snowed", "We''re", "under", "order", "right", "snow", "with", "rightly", "now", "orders"]}, {"sentenceText": "I''ve been snowed under since Monday.", "highlightingPart": "snowed under", "sentenceTranslation": "월요일부터 일에 파묻혀 지냈어.", "practiceQuestion": "Why haven''t I seen you all week?", "practiceQuestionTranslation": "왜 이번 주 내내 코빼기도 안 보였어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/242/practice-examples/80c6d483-e969-4f29-8827-5da385679c4b.webp", "sentenceWords": ["I''ve", "been", "snowed", "under", "since", "Monday"], "sentenceWordChoices": ["snowing", "been", "being", "since", "under", "Monday", "snowed", "Mondays", "I''ve"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00603103638,-0.0383911133,-0.0728149414,0.00559616089,-0.00918579102,-0.0452270508,0.0307769775,0.0277099609,-0.013168335,-0.0364685059,-0.0172271729,0.0213012695,-0.0157165527,0.0226898193,-0.011138916,-0.00537490845,0.0072593689,0.0122680664,0.00629806519,0.0338134766,0.0161132812,0.00482177734,0.0320739746,-0.00214767456,0.0291595459,0.0422668457,0.00299453735,0.0149383545,0.0682373047,-0.0127944946,-0.0319519043,-0.0380859375,-0.00126457214,-0.0278167725,0.0459594727,-0.0179901123,0.0316162109,-0.00247192383,-0.0130615234,-0.0384216309,0.0041809082,-0.0208587646,0.0383300781,0.0281066895,0.00947570801,0.0789794922,-0.00412368774,0.0311737061,0.000930786133,0.0207519531,0.0150375366,0.042175293,-0.000511169434,-0.0396118164,0.0331115723,-0.0294799805,0.0182037354,0.00247001648,0.00960540771,-0.03074646,0.0308990479,-0.0450439453,0.00688552856,0.0357666016,0.00955200195,-0.0648803711,0.0383300781,0.01953125,-0.0463867188,0.0107421875,0.00611495972,0.00287246704,0.00632476807,-0.00635528564,0.0227966309,0.0324707031,-0.0113601685,-0.0169525146,0.0199432373,-0.0390014648,0.0719604492,-0.035