(292,NULL,'CONVERSATION_SKILL','BASIC','EN','KR',129,'Quick question','짧게 하나만 물어볼게','부담 없이 묻는 Quick question','''금방 끝날 질문 하나''라고 미리 알려서 상대의 부담을 낮추는 오프너입니다. 사무실 채팅, 문자, 대면 어디서나 하루에도 몇 번씩 들리는 표현이에요.','Hey, what''s up?','야, 무슨 일이야?','Quick question — is the meeting still at three?','짧게 하나만 물어볼게. 회의 3시 그대로야?',ARRAY['Quick','question','is','the','meeting','still','at','three']::varchar[],ARRAY['the','three','is','questions','Quickly','meeting','at','Quick','question','still','are']::varchar[],NULL,'[{"sentenceText": "Quick question: do we need to bring anything?", "highlightingPart": "Quick question", "sentenceTranslation": "하나만 묻자. 우리 뭐 가져가야 해?", "practiceQuestion": "The barbecue''s at my place this Saturday.", "practiceQuestionTranslation": "이번 토요일에 우리 집에서 바비큐 해.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/292/practice-examples/3064158f-15ed-485a-ad94-32af342cebef.webp", "sentenceWords": ["Quick", "question", "do", "we", "need", "to", "bring", "anything"], "sentenceWordChoices": ["do", "Quick", "something", "bring", "we", "anything", "question", "need", "to", "brought", "does"]}, {"sentenceText": "Sorry, quick question before you go.", "highlightingPart": "quick question", "sentenceTranslation": "미안, 가기 전에 하나만 물어볼게.", "practiceQuestion": "Alright, I''m heading out now.", "practiceQuestionTranslation": "좋아, 나 이제 나간다.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/292/practice-examples/cd74f55c-0448-4118-9465-da418359b205.webp", "sentenceWords": ["Sorry", "quick", "question", "before", "you", "go"], "sentenceWordChoices": ["Sorry", "before", "question", "go", "questions", "quick", "goes", "you", "after"]}, {"sentenceText": "Can I ask a quick question?", "highlightingPart": "quick question", "sentenceTranslation": "질문 하나만 빨리 해도 돼요?", "practiceQuestion": "That wraps up today''s training session.", "practiceQuestionTranslation": "오늘 교육은 여기까지입니다.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/292/practice-examples/bc74d81d-e158-4970-a983-a373db713fd8.webp", "sentenceWords": ["Can", "I", "ask", "a", "quick", "question"], "sentenceWordChoices": ["quick", "quickly", "question", "questions", "Can", "ask", "asks", "I", "a"]}, {"sentenceText": "It''s just a quick question, I promise.", "highlightingPart": "quick question", "sentenceTranslation": "진짜 금방 끝나는 질문이야.", "practiceQuestion": "I''m kind of in the middle of something right now.", "practiceQuestionTranslation": "나 지금 좀 하던 일 중이라.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/292/practice-examples/e54913cc-6344-453a-b04d-d1421bcf5a3c.webp", "sentenceWords": ["It''s", "just", "a", "quick", "question", "I", "promise"], "sentenceWordChoices": ["promise", "just", "promised", "Its", "quick", "question", "It''s", "a", "I", "questions"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0247802734,0.0128097534,-0.0498657227,0.0316772461,-0.021987915,-0.0241088867,0.000710487366,0.0326538086,0.022277832,0.00827026367,-0.00682449341,-0.0193939209,0.0322570801,0.00169372559,-0.0258636475,-0.00248718262,-0.0426330566,-0.00731658936,0.00433349609,-0.00978851318,0.0277557373,0.00609588623,-0.0196685791,-0.00760650635,0.000450611115,0.015838623,-0.00346374512,0.00722503662,0.00785064697,0.00890350342,0.0415344238,-0.0318603516,0.0161895752,-0.0211181641,0.02784729,0.0569152832,0.0196990967,-0.00859069824,-0.020324707,-0.0386657715,0.00774383545,-0.0219573975,0.0214080811,-0.0257568359,0.0247344971,0.0280456543,-0.0141448975,0.058380127,0.0204620361,0.00827026367,-0.0177459717,0.0221252441,0.00481796265,0.0523986816,-0.0123977661,-0.0285491943,-0.00643920898,-0.00019288063,0.0212249756,-0.0309753418,0.0346069336,-0.0663452148,-0.0314331055,0.0405883789,0.0379943848,-0.00323295593,0.0265808105,-0.00075674057,-0.0494384766,0.01612854,-0.0234375,-0.0121154785,-0.0197296143,0.0158843994,0.0131149292,0.0302734375,0.00632476807,0.011680603,-0.00724029541,-0.0115509033,0.0350952148,-0.00955963135,-0.0565795