(293,NULL,'POLITE_EXPRESSION','BASIC','EN','KR',130,'I hate to ask, but','이런 부탁 하기 싫은데','미안한 부탁 앞에 붙이는 I hate to ask, but','''이런 부탁 하기 정말 싫은데''라며 미안함을 먼저 표현하는 부탁 쿠션입니다. 돈, 민폐성 요청처럼 꺼내기 어려운 말의 문턱을 낮춰줘요.','You look like something''s on your mind.','뭔가 할 말 있는 얼굴인데.','I hate to ask, but could I borrow some money until Friday?','이런 부탁 하기 싫은데, 금요일까지 돈 좀 빌릴 수 있을까?',ARRAY['I','hate','to','ask','but','could','I','borrow','some','money','until','Friday']::varchar[],ARRAY['until','by','ask','I','lend','to','money','could','hates','but','I','some','hate','borrow','Friday']::varchar[],NULL,'[{"sentenceText": "I hate to ask, but can you work this Saturday?", "highlightingPart": "I hate to ask, but", "sentenceTranslation": "미안한 부탁인데, 이번 토요일에 일할 수 있어요?", "practiceQuestion": "Did you want to see me about the schedule?", "practiceQuestionTranslation": "스케줄 때문에 저 보자고 하셨어요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/293/practice-examples/f8f4753d-4644-47bb-83d5-e0010d789452.webp", "sentenceWords": ["I", "hate", "to", "ask", "but", "can", "you", "work", "this", "Saturday"], "sentenceWordChoices": ["this", "hate", "ask", "I", "work", "Saturday", "asked", "to", "can", "hates", "you", "works", "but"]}, {"sentenceText": "I hate to ask again, but could you resend it?", "highlightingPart": "I hate to ask", "sentenceTranslation": "또 부탁해서 미안한데, 다시 보내줄 수 있어?", "practiceQuestion": "Were you able to open the file okay?", "practiceQuestionTranslation": "파일 잘 열렸어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/293/practice-examples/c0b35ea7-9ea6-4f6f-8226-a65c2d6b1bf6.webp", "sentenceWords": ["I", "hate", "to", "ask", "again", "but", "could", "you", "resend", "it"], "sentenceWordChoices": ["could", "sent", "it", "hates", "but", "hate", "to", "you", "again", "ask", "resend", "asking", "I"]}, {"sentenceText": "I hate to bring this up, but you still owe me dinner.", "highlightingPart": "I hate to bring this up", "sentenceTranslation": "이 얘기 꺼내기 싫은데, 너 나한테 저녁 사기로 한 거 아직이야.", "practiceQuestion": "So what should we do this Friday night?", "practiceQuestionTranslation": "그래서 이번 주 금요일 밤에 뭐 할까?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/293/practice-examples/dd5841ee-2376-4ba0-99e1-0ae8e90811c9.webp", "sentenceWords": ["I", "hate", "to", "bring", "this", "up", "but", "you", "still", "owe", "me", "dinner"], "sentenceWordChoices": ["hates", "hate", "to", "bring", "owes", "up", "me", "I", "dinner", "owe", "still", "but", "this", "you", "brings"]}, {"sentenceText": "I hate to say it, but he was right.", "highlightingPart": "I hate to say it", "sentenceTranslation": "인정하기 싫지만 걔 말이 맞았어.", "practiceQuestion": "So how did his prediction about the launch turn out?", "practiceQuestionTranslation": "그래서 걔가 출시 관련해서 예상했던 거 어떻게 됐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/293/practice-examples/339687db-3976-463f-ad1b-63307b07f9b6.webp", "sentenceWords": ["I", "hate", "to", "say", "it", "but", "he", "was", "right"], "sentenceWordChoices": ["I", "to", "right", "hates", "says", "he", "hate", "it", "were", "was", "say", "but"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00878143311,-0.0225982666,-0.0552368164,0.008934021,0.0101013184,-0.033996582,-0.0366210938,0.00532913208,0.00691604614,0.0061416626,-0.0278320312,-0.0298919678,0.0160064697,0.0254669189,-0.0202026367,-0.00152111053,-0.00221252441,0.0204925537,-0.0126876831,0.0368041992,-0.0195159912,-0.00564575195,-0.0455322266,0.0312042236,0.0109176636,0.0193786621,-0.00426864624,-0.041229248,0.0546264648,0.0221405029,-0.0344238281,-0.0231170654,-0.013885498,-0.0347900391,0.0187683105,0.0723876953,-0.0205535889,0.00581359863,0.0394592285,-0.0145263672,0.0191040039,-0.0164337158,0.060333252,-0.0368652344,0.0264434814,0.0458068848,-0.0570678711,-0.00358581543,0.0188751221,-0.0188293457,0.000336647034,0.0287628174,-0.00206184387,0.0592651367,0.002576828,-0.024520874,-0.000547409058,-0.0156555176,0.0124359131,-0.01863098