(314,NULL,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',151,'one of those','(누구나 아는) 그런 ~','서로 아는 ''그런 거''를 가리키는 one of those','듣는 사람도 바로 떠올릴 수 있는 ''그런 종류의 것''을 가리키는 표현입니다. It''s one of those days라고 하면 ''왜 그런 날 있잖아'' 하는 공감을 깔고 말하는 느낌이에요.','Rough day? You look worn out.','힘든 하루였어? 지쳐 보이네.','It''s just been one of those days.','오늘 그냥 되는 일이 없는 그런 날이야.',ARRAY['It''s','just','been','one','of','those','days']::varchar[],ARRAY['being','of','It''s','one','been','days','those','just','that','day']::varchar[],NULL,'[{"sentenceText": "It turned out to be one of those things you buy and never use.", "highlightingPart": "one of those", "sentenceTranslation": "사 놓고 안 쓰게 되는 그런 물건이 돼 버렸어.", "practiceQuestion": "Why did you buy that gadget?", "practiceQuestionTranslation": "그 기계는 왜 산 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/314/practice-examples/69b09048-f44c-4882-951d-680157b7bc2e.webp", "sentenceWords": ["It", "turned", "out", "to", "be", "one", "of", "those", "things", "you", "buy", "and", "never", "use"], "sentenceWordChoices": ["buy", "those", "of", "one", "that", "thing", "It", "never", "you", "things", "using", "use", "and", "be", "to", "out", "turned"]}, {"sentenceText": "It''s one of those places where you order at the counter.", "highlightingPart": "one of those", "sentenceTranslation": "카운터에서 주문하는 그런 데야.", "practiceQuestion": "What kind of restaurant is it?", "practiceQuestionTranslation": "거기 어떤 식당이야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/314/practice-examples/8807ed80-469d-41ee-aad8-7ff08caca984.webp", "sentenceWords": ["It''s", "one", "of", "those", "places", "where", "you", "order", "at", "the", "counter"], "sentenceWordChoices": ["places", "those", "one", "It''s", "you", "where", "of", "that", "the", "order", "place", "at", "counter", "which"]}, {"sentenceText": "It''s one of those songs you hear everywhere.", "highlightingPart": "one of those", "sentenceTranslation": "어딜 가나 나오는 그런 노래잖아.", "practiceQuestion": "Why does this song sound so familiar?", "practiceQuestionTranslation": "이 노래 왜 이렇게 익숙하지?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/314/practice-examples/4059e676-b7b4-471c-be9c-46d808a65f30.webp", "sentenceWords": ["It''s", "one", "of", "those", "songs", "you", "hear", "everywhere"], "sentenceWordChoices": ["It''s", "song", "hears", "that", "everywhere", "of", "hear", "those", "songs", "one", "you"]}, {"sentenceText": "It was one of those meetings that could''ve been an email.", "highlightingPart": "one of those", "sentenceTranslation": "이메일로 해도 됐을 그런 회의였어.", "practiceQuestion": "How was the meeting?", "practiceQuestionTranslation": "회의 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/314/practice-examples/c196748b-93d2-409a-b764-8bd4d6a51360.webp", "sentenceWords": ["It", "was", "one", "of", "those", "meetings", "that", "could''ve", "been", "an", "email"], "sentenceWordChoices": ["an", "this", "being", "been", "It", "those", "email", "that", "was", "of", "meetings", "meeting", "could''ve", "one"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[-0.00717544556,-0.0226745605,-0.00396347046,0.000816345215,-0.000532150269,-0.0458374023,-0.0183258057,0.0247955322,0.0151519775,-0.0223236084,-0.00691986084,-0.0454711914,0.00484466553,-0.0449523926,-0.0599060059,0.0101089478,-0.00260162354,-0.000518321991,0.0308227539,0.0158233643,0.0335083008,0.0171813965,0.0188140869,0.0381774902,-0.0128479004,-0.00398635864,-0.0154342651,0.012878418,0.0106201172,-0.000537395477,-0.00448226929,-0.0291137695,0.0303344727,-0.0786132812,-0.0130767822,0.014289856,0.0445861816,-0.0102539062,-0.00617599487,-0.0511779785,0.0246124268,-0.0176849365,0.0237579346,-0.0440368652,0.019317627,0.0147857666,-0.0353088379,0.00471878052,-0.0339355469,0.0105514526,-0.0119781494,0.0198974609,-0.000252008438,0.0513916016,0.0114593506,-0.0370178223,-0.0263214111,0.0345153809,0.0261993408,-0.0336608887,0.0203094482,-0.0333251953,0.00518417358,0.