(327,NULL,'POLITE_EXPRESSION','BASIC','EN','KR',164,'I hate to say it','이런 말 하기 그렇지만','꺼내기 어려운 말을 여는 I hate to say it','반갑지 않은 이야기를 꺼내기 전에 붙이는 쿠션 표현입니다. ''이런 말 하기 그렇지만''이라고 미리 깔아서 상대가 받을 충격을 한 번 줄여줘요.','The night is still young!','아직 초저녁이잖아!','I hate to say it, but we should head home.','아쉽지만 이제 집에 가야 할 것 같아.',ARRAY['I','hate','to','say','it','but','we','should','head','home']::varchar[],ARRAY['but','it','I','should','to','we','hates','head','home','hate','heads','saying','say']::varchar[],NULL,'[{"sentenceText": "I hate to say it, but it needs more work.", "highlightingPart": "I hate to say it", "sentenceTranslation": "이런 말 하기 그렇지만 손을 더 봐야겠어.", "practiceQuestion": "How does my presentation look?", "practiceQuestionTranslation": "내 발표 자료 어때?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/327/practice-examples/04082dd8-dd07-44eb-8610-f9277695ae16.webp", "sentenceWords": ["I", "hate", "to", "say", "it", "but", "it", "needs", "more", "work"], "sentenceWordChoices": ["say", "but", "hate", "I", "need", "needs", "to", "hates", "it", "work", "more", "it", "saying"]}, {"sentenceText": "I hate to say it, but it''s not looking good.", "highlightingPart": "I hate to say it", "sentenceTranslation": "말하기 좀 그런데, 상황이 안 좋아.", "practiceQuestion": "We can still win this, right?", "practiceQuestionTranslation": "우리 아직 이길 수 있지?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/327/practice-examples/1ff89651-e90d-4dcc-bb6a-09d054572758.webp", "sentenceWords": ["I", "hate", "to", "say", "it", "but", "it''s", "not", "looking", "good"], "sentenceWordChoices": ["hate", "not", "to", "looks", "say", "saying", "looking", "good", "it", "I", "but", "hates", "it''s"]}, {"sentenceText": "I hate to say it, but I told you so.", "highlightingPart": "I hate to say it", "sentenceTranslation": "이런 말 하긴 싫지만, 내가 그랬잖아.", "practiceQuestion": "Was I wrong about him?", "practiceQuestionTranslation": "내가 걔를 잘못 본 건가?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/327/practice-examples/98fedc9c-a3c0-4bc3-9cfb-be8b20401755.webp", "sentenceWords": ["I", "hate", "to", "say", "it", "but", "I", "told", "you", "so"], "sentenceWordChoices": ["say", "you", "it", "I", "saying", "hates", "to", "hate", "but", "I", "so", "told", "tell"]}, {"sentenceText": "I hate to say it, but it doesn''t suit you.", "highlightingPart": "I hate to say it", "sentenceTranslation": "미안한 말이지만 너랑 안 어울려.", "practiceQuestion": "This jacket was so expensive.", "practiceQuestionTranslation": "이 재킷 엄청 비쌌단 말이야.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/327/practice-examples/b1e384b3-ccb2-4998-aa71-042468ba72f0.webp", "sentenceWords": ["I", "hate", "to", "say", "it", "but", "it", "doesn''t", "suit", "you"], "sentenceWordChoices": ["to", "say", "don''t", "it", "I", "suit", "but", "suits", "you", "doesn''t", "it", "hate", "hates"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0131225586,-0.0269165039,-0.0328063965,0.0162963867,0.00625228882,0.0127105713,-0.0162353516,-0.0268859863,-0.00632858276,-0.00548171997,-0.0228271484,-0.0305023193,0.0267486572,-0.0116424561,-0.00924682617,-0.00643157959,-0.0270233154,0.0134124756,0.00898742676,0.000202894211,0.0192260742,0.00559616089,-0.0207061768,0.0201416016,0.0517578125,0.0201568604,0.0323791504,0.0189361572,0.0623168945,-0.0106887817,-0.0199584961,-0.0135269165,0.0189361572,-0.0455932617,0.0269622803,0.01197052,-0.0159606934,0.00312042236,0.0266571045,-0.0294647217,0.0285339355,-0.00846862793,0.0460205078,-0.0372009277,0.0213317871,0.0606689453,-0.0299682617,-0.0172424316,0.00618362427,-0.0196838379,-0.0286865234,0.0498046875,-0.00512695312,0.0939331055,0.0102996826,-0.0608215332,0.0206756592,-0.00151062012,0.0182342529,-0.0757446289,0.0114364624,-0.0234222412,-0.00661849976,0.0433044434,0.000288009644,-0.0154800415,0.0459899902,-0.0285339355,-0.0121994019,0.0359191895,0.00166320801,-0.0124359131,-0.0152740479,0.00580215454,0.0106430054,-0.0516662598,-0.0054016113