(328,NULL,'POLITE_EXPRESSION','BASIC','EN','KR',165,'I know it''s a lot to ask','무리한 부탁인 건 알지만','조심스러운 부탁의 쿠션 I know it''s a lot to ask','부담스러운 부탁을 하기 전에 ''무리인 거 알아''라고 먼저 인정하고 들어가는 표현입니다. 상대가 거절할 여지를 남겨주는 예의 바른 쿠션이에요.','What''s up? You look like you need something.','왜? 뭐 부탁할 거 있는 표정인데.','I know it''s a lot to ask, but could you cover my shift tomorrow?','무리한 부탁인 거 아는데, 내일 내 근무 좀 대신해 줄 수 있어?',ARRAY['I','know','it''s','a','lot','to','ask','but','could','you','cover','my','shift','tomorrow']::varchar[],ARRAY['I','know','covers','lot','you','cover','ask','to','could','tomorrow','a','but','my','shift','asking','it''s','knows']::varchar[],NULL,'[{"sentenceText": "Yeah... I know it''s a lot to ask, but could you help me pack?", "highlightingPart": "I know it''s a lot to ask", "sentenceTranslation": "응… 무리인 거 아는데 짐 싸는 것 좀 도와줄래?", "practiceQuestion": "You''re moving this Saturday, right?", "practiceQuestionTranslation": "너 이번 토요일에 이사하지?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/328/practice-examples/e959dbcc-b322-48ac-85af-ccfbfceb9df3.webp", "sentenceWords": ["Yeah", "I", "know", "it''s", "a", "lot", "to", "ask", "but", "could", "you", "help", "me", "pack"], "sentenceWordChoices": ["it''s", "to", "but", "know", "help", "I", "knows", "packing", "could", "lot", "Yeah", "asking", "pack", "you", "me", "a", "ask"]}, {"sentenceText": "I know it''s a lot to ask, but can I stay at your place for a few days?", "highlightingPart": "I know it''s a lot to ask", "sentenceTranslation": "염치없지만 며칠만 너네 집에 있어도 될까?", "practiceQuestion": "Is something wrong with your apartment?", "practiceQuestionTranslation": "집에 무슨 문제 있어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/328/practice-examples/99e68544-72f7-4624-ab0c-a8e0d200e842.webp", "sentenceWords": ["I", "know", "it''s", "a", "lot", "to", "ask", "but", "can", "I", "stay", "at", "your", "place", "for", "a", "few", "days"], "sentenceWordChoices": ["I", "at", "stay", "knows", "I", "for", "your", "few", "lot", "a", "asking", "day", "ask", "a", "days", "can", "but", "know", "place", "it''s", "to"]}, {"sentenceText": "I know it''s a lot to ask, but could you review the whole thing by tomorrow?", "highlightingPart": "I know it''s a lot to ask", "sentenceTranslation": "무리한 부탁인 건 아는데 내일까지 전체를 검토해 줄 수 있을까?", "practiceQuestion": "How''s the draft coming along?", "practiceQuestionTranslation": "초안은 잘돼 가?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/328/practice-examples/2d8863bc-b70c-4567-9378-2e59e41e721c.webp", "sentenceWords": ["I", "know", "it''s", "a", "lot", "to", "ask", "but", "could", "you", "review", "the", "whole", "thing", "by", "tomorrow"], "sentenceWordChoices": ["thing", "to", "I", "until", "but", "knows", "know", "review", "ask", "the", "could", "whole", "lot", "a", "by", "you", "asking", "tomorrow", "it''s"]}, {"sentenceText": "I know it''s a lot to ask, but could you walk my dog this week too?", "highlightingPart": "I know it''s a lot to ask", "sentenceTranslation": "좀 과한 부탁인데, 이번 주에도 우리 개 산책시켜 줄 수 있어?", "practiceQuestion": "Need anything before I head out?", "practiceQuestionTranslation": "나 나가기 전에 뭐 필요한 거 있어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/328/practice-examples/a0dbc681-d61a-4794-b560-8c16b7cc1490.webp", "sentenceWords": ["I", "know", "it''s", "a", "lot", "to", "ask", "but", "could", "you", "walk", "my", "dog", "this", "week", "too"], "sentenceWordChoices": ["but", "this", "could", "it''s", "a", "ask", "lot", "my", "dog", "walk", "know", "knows", "too", "asking", "I", "you", "to", "week"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0378112793,-0.0450134277,-0.0376281738,0.00450897217,-0.00904083252,-0.010345459,-0.035949707,-0.00277900696,-0.00874328613,0.0428771973,0.0255279541,-0.0197296143,-0.0109329224,-0.0010881424,-0.0275268555,-0.00209236145,-0.0155639648,0.0120697021,0.0231323242,0.0193634033,-0.028213501,-0.00359725952,-0.0242767334,-0.0120697021,0.0276641