(415,NULL,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',252,'or something (like that)','뭐 그런 거','대충 뭉뚱그리기 or something (like that)','정확히 기억나지 않거나 굳이 정확할 필요가 없을 때 문장 끝에 붙여 "뭐 그런 거"라고 뭉뚱그리는 표현이다. 세부사항에 자신 없을 때 빠져나갈 구멍을 만들어준다. We could grab coffee or something처럼 제안 뒤에 붙이면 부담을 덜어주는 용도로도 쓴다.','What does your roommate''s brother do?','네 룸메 오빠는 무슨 일 해?','He''s an engineer or something like that.','엔지니어인가 뭐 그런 거 하던데.',ARRAY['He''s','an','engineer','or','something','like','that']::varchar[],ARRAY['an','that','He''s','or','something','likes','anything','a','engineer','like']::varchar[],NULL,'[{"sentenceText": "Renovation or something. I didn''t read the sign closely.", "highlightingPart": "or something", "sentenceTranslation": "리모델링인가 뭔가. 안내문을 자세히 안 봤어.", "practiceQuestion": "Why was the library closed today?", "practiceQuestionTranslation": "도서관 오늘 왜 닫았대?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/415/practice-examples/7f7c9a26-2ce3-4129-9d81-5936d9fb7ce9.webp", "sentenceWords": ["Renovation", "or", "something", "I", "didn''t", "read", "the", "sign", "closely"], "sentenceWordChoices": ["Renovation", "something", "anything", "closely", "the", "read", "I", "or", "signs", "sign", "didn''t"]}, {"sentenceText": "Wanna watch a movie or something?", "highlightingPart": "or something", "sentenceTranslation": "영화나 뭐 그런 거 볼래?", "practiceQuestion": "I''m so bored tonight.", "practiceQuestionTranslation": "오늘 밤 너무 심심해.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/415/practice-examples/24db1128-1ccf-4abe-a686-ca472e27fd68.webp", "sentenceWords": ["Wanna", "watch", "a", "movie", "or", "something"], "sentenceWordChoices": ["a", "Wanna", "or", "movie", "something", "anything", "movies", "watch", "watches"]}, {"sentenceText": "At a book club or something like that.", "highlightingPart": "or something like that", "sentenceTranslation": "독서 모임인가 뭐 그런 데서.", "practiceQuestion": "How did those two meet?", "practiceQuestionTranslation": "걔네 둘은 어떻게 만났대?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/415/practice-examples/32736d39-d070-4837-b1c0-c20f1d7b3a1c.webp", "sentenceWords": ["At", "a", "book", "club", "or", "something", "like", "that"], "sentenceWordChoices": ["club", "book", "that", "this", "At", "anything", "like", "or", "books", "a", "something"]}, {"sentenceText": "Twenty dollars or something like that.", "highlightingPart": "or something like that", "sentenceTranslation": "20달러인가 뭐 그 정도였어요.", "practiceQuestion": "What was the application fee again?", "practiceQuestionTranslation": "신청 수수료가 얼마였죠?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/415/practice-examples/cf98a374-59d0-4cb9-9481-ad5498505594.webp", "sentenceWords": ["Twenty", "dollars", "or", "something", "like", "that"], "sentenceWordChoices": ["something", "that", "Twenty", "dollars", "this", "or", "dollar", "like", "anything"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.021774292,-0.0296020508,-0.0608215332,0.0244903564,-0.0274047852,-0.0290222168,0.044342041,0.00933837891,-0.00980377197,-0.0259857178,-0.0164031982,-0.0491943359,0.0219421387,-0.0294647217,-0.0203399658,0.0461120605,-0.0188140869,0.0325012207,0.00156784058,0.0336608887,0.000272750854,0.0306396484,0.0221710205,0.0502929688,0.0276031494,0.00103473663,0.0159912109,-0.00827789307,0.0328674316,-0.0134811401,0.0107803345,-0.0366210938,0.0567321777,-0.0616760254,-0.00179100037,0.0396728516,0.0418701172,-0.00835418701,0.0234680176,-0.024017334,-0.00226783752,-0.0531921387,0.0548095703,-0.0213928223,0.0191497803,0.0100708008,-0.0276184082,-0.0143890381,-0.0113525391,0.0016374588,-0.0177307129,-0.0185089111,0.00243377686,0.049621582,0.0116348267,-0.0300292969,-0.0137863159,0.0308074951,0.024520874,-0.0375671387,0.00155544281,-0.0303497314,0.0238342285,0.0272827148,-0.027130127,-0.0226135254,-0.00138473511,0.0305328369,-0.0289306641,0.0433349609,-0.0313720703,-0.0120773315,-0.0261535645,-0.023223877,0.0222625732,-0.006439208