(538,NULL,'TRAVEL_MOVEMENT','CLASSIC_COMMON','EN','KR',375,'safe and sound','무사히, 탈 없이','무사 도착 safe and sound','다치거나 잃어버린 것 없이 무사하다는 뜻의 오래된 짝꿍 표현이다. 여행이나 이동 후에 잘 도착했다고 알릴 때 가장 많이 쓰고, 사람뿐 아니라 택배 같은 물건에도 쓸 수 있다. safe와 sound가 운을 맞춘 관용구라 순서를 바꾸지 않는다.','Did you land okay? Text me!','잘 도착했어? 문자 줘!','Just landed, safe and sound.','방금 무사히 도착했어.',ARRAY['Just','landed','safe','and','sound']::varchar[],ARRAY['Just','sound','safe','lands','and','sounds','safely','landed']::varchar[],NULL,'[{"sentenceText": "Long, but I got here safe and sound.", "highlightingPart": "safe and sound", "sentenceTranslation": "길긴 했는데 무사히 도착했어.", "practiceQuestion": "How was the overnight bus?", "practiceQuestionTranslation": "심야버스 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/538/practice-examples/e264f18e-82c5-4165-9e15-9a9b9c2f4869.webp", "sentenceWords": ["Long", "but", "I", "got", "here", "safe", "and", "sound"], "sentenceWordChoices": ["safely", "I", "Long", "sounds", "sound", "safe", "and", "here", "but", "hear", "got"]}, {"sentenceText": "Yep, it arrived safe and sound.", "highlightingPart": "safe and sound", "sentenceTranslation": "응, 멀쩡하게 잘 왔어.", "practiceQuestion": "Did your package finally show up?", "practiceQuestionTranslation": "네 택배 드디어 왔어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/538/practice-examples/d950a7fa-a7a2-4cd0-b907-0d1fff34ef19.webp", "sentenceWords": ["Yep", "it", "arrived", "safe", "and", "sound"], "sentenceWordChoices": ["arrived", "arrives", "Yep", "it", "and", "safe", "sound", "sounds", "safely"]}, {"sentenceText": "It did, but we made it home safe and sound.", "highlightingPart": "safe and sound", "sentenceTranslation": "응, 그래도 무사히 집에 왔어.", "practiceQuestion": "I heard your flight got delayed.", "practiceQuestionTranslation": "비행기 지연됐다며.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/538/practice-examples/40d32b34-956a-406e-a8ba-7550eac8a0e4.webp", "sentenceWords": ["It", "did", "but", "we", "made", "it", "home", "safe", "and", "sound"], "sentenceWordChoices": ["but", "sounds", "and", "makes", "safely", "It", "it", "made", "did", "we", "home", "safe", "sound"]}, {"sentenceText": "Safe and sound, just badly sunburned.", "highlightingPart": "Safe and sound", "sentenceTranslation": "무사히 왔는데 얼굴만 새까맣게 탔어.", "practiceQuestion": "Did your roommate get back from the hike?", "practiceQuestionTranslation": "네 룸메 등산 갔다가 돌아왔어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/538/practice-examples/f188574c-b470-45f8-8750-9450df6a7f77.webp", "sentenceWords": ["Safe", "and", "sound", "just", "badly", "sunburned"], "sentenceWordChoices": ["and", "Safe", "safely", "just", "sound", "sounds", "sunburned", "badly", "bad"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0570373535,0.00572967529,-0.0663452148,0.00365447998,-0.0286865234,0.019821167,-0.033416748,0.0110244751,0.0146636963,-0.0331115723,-0.00353622437,0.00436019897,-0.0141906738,0.00877380371,0.00139141083,-0.000105142593,-0.0520629883,-0.0142822266,0.0366516113,-0.0239715576,0.00350189209,-0.0221862793,-0.0294647217,0.0271911621,0.0156860352,-0.0138244629,0.00743484497,0.000874519348,0.0361633301,0.012336731,0.026473999,-0.0273742676,0.0196380615,-0.0365600586,0.0225219727,-0.00112533569,-0.00636291504,0.0131149292,-0.0680541992,-0.0844116211,0.0328063965,-0.00601577759,0.029876709,0.00336265564,0.0338134766,0.0463256836,-0.0074005127,0.00908660889,0.0550842285,0.0326843262,0.000393390656,0.0225219727,-0.0166320801,0.0562744141,-0.0487060547,-0.0293273926,0.0129623413,0.00307273865,0.0244140625,-0.0594177246,0.000912666321,0.0093536377,0.00253677368,0.0412902832,0.0396118164,-0.000120639801,-0.0175476074,0.0213470459,-0.00919342041,-0.0275421143,0.0380859375,-0.00941467285,-0.00403594971,0.00563430786,-0.0218963623,0.00512695312,0.000313043594,-0.00780487061,0.00667572021,-0.0258331299,-0.00397109985,-0.0278167725,-0.0130157471,-0.0272369385,-0.0361633301,-0.0025100708,-0.0