(608,NULL,'TRAVEL_MOVEMENT','BASIC','EN','KR',445,'bucket list','버킷리스트, 꼭 해보고 싶은 일 목록','죽기 전 소망 목록 bucket list','죽기 전에 꼭 해보고 싶은 일들의 목록을 말한다. kick the bucket(죽다)이라는 관용구에서 나온 말이지만, 지금은 어두운 느낌 없이 여행·도전 얘기에 두루 쓰는 표준 표현이 됐다. It''s on my bucket list 형태로 제일 많이 쓴다.','Why are you so obsessed with seeing the northern lights?','너 오로라 보는 거에 왜 그렇게 집착해?','It''s been on my bucket list forever.','그거 옛날부터 내 버킷리스트에 있었거든.',ARRAY['It''s','been','on','my','bucket','list','forever']::varchar[],ARRAY['my','on','It''s','list','buckets','been','lists','at','bucket','forever']::varchar[],NULL,'[{"sentenceText": "Knock out my bucket list, starting with Iceland.", "highlightingPart": "bucket list", "sentenceTranslation": "버킷리스트부터 해치워야지, 아이슬란드부터.", "practiceQuestion": "What''s the first thing you''d do with a free year?", "practiceQuestionTranslation": "1년이 통째로 생기면 제일 먼저 뭐 할 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/608/practice-examples/64d3a86f-732f-47d4-b443-41f4e2339b94.webp", "sentenceWords": ["Knock", "out", "my", "bucket", "list", "starting", "with", "Iceland"], "sentenceWordChoices": ["buckets", "lists", "starts", "Knock", "with", "out", "bucket", "my", "list", "starting", "Iceland"]}, {"sentenceText": "Terrifying, but I finally crossed it off my bucket list.", "highlightingPart": "bucket list", "sentenceTranslation": "완전 무서웠는데, 드디어 버킷리스트에서 하나 지웠어.", "practiceQuestion": "Was skydiving scary?", "practiceQuestionTranslation": "스카이다이빙 무서웠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/608/practice-examples/0c3af3c0-1a6f-48c6-b91e-62f955dfb372.webp", "sentenceWords": ["Terrifying", "but", "I", "finally", "crossed", "it", "off", "my", "bucket", "list"], "sentenceWordChoices": ["it", "I", "lists", "but", "list", "bucket", "finally", "crossed", "Terrifying", "buckets", "my", "off", "cross"]}, {"sentenceText": "Diving with sea turtles is on my bucket list.", "highlightingPart": "bucket list", "sentenceTranslation": "바다거북이랑 다이빙하는 게 내 버킷리스트라서.", "practiceQuestion": "Why did you sign up for the scuba class?", "practiceQuestionTranslation": "스쿠버 수업은 왜 신청한 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/608/practice-examples/ebeaa2c8-0cdc-420c-b0d5-4a698ef086a4.webp", "sentenceWords": ["Diving", "with", "sea", "turtles", "is", "on", "my", "bucket", "list"], "sentenceWordChoices": ["Diving", "sea", "are", "turtle", "bucket", "on", "list", "turtles", "with", "lists", "is", "my"]}, {"sentenceText": "Yeah, I made a little college bucket list.", "highlightingPart": "bucket list", "sentenceTranslation": "응, 대학 버킷리스트를 소소하게 만들었어.", "practiceQuestion": "Anything you want to do before graduation?", "practiceQuestionTranslation": "졸업 전에 하고 싶은 거 있어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/608/practice-examples/634d5ccb-35f8-4eb1-8010-bf8b89f28818.webp", "sentenceWords": ["Yeah", "I", "made", "a", "little", "college", "bucket", "list"], "sentenceWordChoices": ["lists", "list", "a", "make", "colleges", "I", "made", "college", "little", "Yeah", "bucket"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0200500488,-0.00522232056,-0.0621337891,-0.0151138306,-0.0701904297,-0.0378112793,-0.00143241882,0.0223999023,0.00784301758,0.0251922607,0.0147628784,0.00214385986,-0.00994873047,-0.00106048584,-0.0174255371,0.0199584961,-0.0446472168,0.0249481201,0.0358276367,-0.035736084,-0.00638580322,-0.0186157227,-0.00200080872,0.0446777344,0.00311088562,0.0169525146,0.0207977295,0.00657272339,0.00468826294,-0.0155258179,0.00140571594,-0.0347900391,0.00415420532,-0.00952911377,0.0455322266,-0.0193328857,0.0617980957,0.00891876221,-0.000205159187,-0.0372314453,0.0198974609,-0.0219421387,0.0305175781,0.00773620605,0.00704193115,0.0767822266,0.00821685791,-0.00981903076,0.0160064697,0.0277862549,-0.0177307129,0.0492858887,-0.000457763672,0.0611877441,0.000236868858,-0.0270843506,-0.0143356323,0.000993728638,0.00794219971,0.013633728,0.00878143311,-0.0143051147,-0.0179443