(622,NULL,'DAILY_ROUTINE','SLANG_NEOLOGISM','EN','KR',459,'food coma','식곤증, 과식 후 몰려오는 졸음','먹고 기절 food coma','과식한 뒤 몰려오는 졸음과 무기력을 "음식 혼수상태"에 빗댄 표현이다. in a food coma 형태로 자주 쓰고, 추수감사절이나 뷔페 다녀온 뒤 단골로 등장한다. 캐주얼한 표현이라 친구 사이 수다에 딱 맞는다.','Why are you lying on the couch already?','왜 벌써 소파에 뻗어 있어?','That buffet put me in a food coma.','그 뷔페 먹고 완전 기절 상태야.',ARRAY['That','buffet','put','me','in','a','food','coma']::varchar[],ARRAY['coma','on','me','in','comas','a','food','put','buffet','That','puts']::varchar[],NULL,'[{"sentenceText": "Amazing. I was in a food coma for hours.", "highlightingPart": "food coma", "sentenceTranslation": "최고였어. 몇 시간 동안 식곤증으로 뻗어 있었다니까.", "practiceQuestion": "How was Thanksgiving dinner at her place?", "practiceQuestionTranslation": "걔네 집 추수감사절 저녁 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/622/practice-examples/7f5d231e-ed3a-4c50-beba-eca73cc540b7.webp", "sentenceWords": ["Amazing", "I", "was", "in", "a", "food", "coma", "for", "hours"], "sentenceWordChoices": ["in", "was", "food", "for", "I", "coma", "a", "were", "hours", "hour", "Amazing", "comas"]}, {"sentenceText": "Bad idea. I always get a food coma.", "highlightingPart": "food coma", "sentenceTranslation": "그건 별로야. 나 밥 먹으면 꼭 식곤증 와.", "practiceQuestion": "Want to study right after lunch?", "practiceQuestionTranslation": "점심 먹고 바로 공부할래?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/622/practice-examples/4ac5fe82-72e2-4f6c-bfbb-c498fe9c2f31.webp", "sentenceWords": ["Bad", "idea", "I", "always", "get", "a", "food", "coma"], "sentenceWordChoices": ["I", "Bad", "a", "comas", "food", "idea", "gets", "coma", "foods", "get", "always"]}, {"sentenceText": "Food coma. He ate two burritos at lunch.", "highlightingPart": "Food coma", "sentenceTranslation": "먹고 기절했어. 점심에 부리토 두 개 먹었거든.", "practiceQuestion": "Where''s your roommate? He missed the meeting.", "practiceQuestionTranslation": "네 룸메 어디 갔어? 회의 빠졌던데.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/622/practice-examples/4b88ae4d-4072-478a-907c-65c7cdca0ef5.webp", "sentenceWords": ["Food", "coma", "He", "ate", "two", "burritos", "at", "lunch"], "sentenceWordChoices": ["burrito", "lunch", "Food", "two", "He", "burritos", "in", "coma", "at", "ate", "eat"]}, {"sentenceText": "No way, I don''t want a food coma before class.", "highlightingPart": "food coma", "sentenceTranslation": "절대 안 돼, 수업 전에 식곤증 오면 안 돼.", "practiceQuestion": "Should we order more food?", "practiceQuestionTranslation": "음식 더 시킬까?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/622/practice-examples/e5a74025-3bd3-49f4-8948-db68c7a756a4.webp", "sentenceWords": ["No", "way", "I", "don''t", "want", "a", "food", "coma", "before", "class"], "sentenceWordChoices": ["I", "food", "before", "don''t", "wants", "No", "comas", "a", "doesn''t", "way", "coma", "want", "class"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[-0.0134735107,0.000754356384,-0.0910644531,-0.0288085938,-0.0120697021,-0.0260314941,0.0205535889,0.0613708496,0.00799560547,-0.0307922363,0.0160827637,0.0334777832,0.0195922852,-0.0367126465,-0.0235443115,-0.0116195679,-0.0405578613,0.000508785248,-0.0143432617,0.0207824707,0.0183410645,-0.00176429749,-0.00810241699,0.0113449097,-0.00449371338,0.0608825684,0.0324401855,0.0337524414,0.0166320801,-0.0248718262,-0.024887085,-0.0229034424,0.0215301514,-0.0874633789,0.0208435059,-0.0180206299,0.00229263306,0.0319213867,-0.0460510254,-0.0109939575,0.00579452515,0.0265655518,0.0490112305,-0.00442504883,0.029083252,0.0281982422,-0.0410461426,0.0313110352,0.0380249023,0.0317382812,-0.01222229,0.001039505,-0.00957489014,0.0224304199,0.0276794434,0.00751876831,-0.0221405029,0.029586792,0.0303192139,-0.0100479126,0.0316772461,-0.00979614258,0.0545349121,0.0259552002,0.00618362427,-0.0225372314,0.00885009766,-0.0186767578,-0.0181732178,0.0345458984,0.0173187256,-0.0106048584,-0.0542907715,0.0175628662,0.0391845703,-0.0167694092,-0.0347900391,-0.026885