(644,NULL,'WORK_STUDY','SLANG_NEOLOGISM','EN','KR',481,'locked in','초집중 모드인, 완전히 몰입한','초집중 모드 locked in','딴생각 없이 목표에만 완전히 몰입한 상태를 말하는 슬랭이다. 원래 스포츠에서 쓰이다가 2024년 무렵부터 시험공부, 운동, 작업 전반으로 퍼졌다. 예약을 확정한다는 뜻의 lock it in과는 다른 표현이니 헷갈리지 않게 주의해야 한다.','Want to grab dinner with us tonight?','오늘 밤에 우리랑 저녁 먹을래?','Can''t. Finals week. I''m locked in until Friday.','안 돼. 기말 주간이라 금요일까지 초집중 모드야.',ARRAY['Can''t','Finals','week','I''m','locked','in','until','Friday']::varchar[],ARRAY['by','locks','in','on','I''m','until','Friday','Finals','locked','week','Can''t']::varchar[],NULL,'[{"sentenceText": "She''s locked in. Big exam tomorrow.", "highlightingPart": "locked in", "sentenceTranslation": "초집중 모드야. 내일 큰 시험 있거든.", "practiceQuestion": "Why is your roommate ignoring everyone?", "practiceQuestionTranslation": "네 룸메 왜 다 무시하고 있어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/644/practice-examples/8cd00241-df1f-42ee-ac60-cb71f7c38f12.webp", "sentenceWords": ["She''s", "locked", "in", "Big", "exam", "tomorrow"], "sentenceWordChoices": ["Big", "in", "on", "She''s", "locking", "tonight", "exam", "locked", "tomorrow"]}, {"sentenceText": "I got locked in and didn''t touch my phone for six hours.", "highlightingPart": "locked in", "sentenceTranslation": "완전 몰입해서 여섯 시간 동안 폰도 안 봤어.", "practiceQuestion": "How did you finish the project so fast?", "practiceQuestionTranslation": "프로젝트 어떻게 그렇게 빨리 끝냈어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/644/practice-examples/f90161e7-110d-4eeb-997a-8a496ddd3ce0.webp", "sentenceWords": ["I", "got", "locked", "in", "and", "didn''t", "touch", "my", "phone", "for", "six", "hours"], "sentenceWordChoices": ["my", "locked", "didn''t", "touched", "get", "hours", "for", "touch", "got", "during", "phone", "six", "and", "in", "I"]}, {"sentenceText": "Totally locked in. Nothing can distract me.", "highlightingPart": "locked in", "sentenceTranslation": "완전 집중 상태야. 아무것도 방해 못 해.", "practiceQuestion": "Are you ready for the game tonight?", "practiceQuestionTranslation": "오늘 밤 경기 준비됐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/644/practice-examples/74b37c0f-c148-49e1-a418-2b69fca820b5.webp", "sentenceWords": ["Totally", "locked", "in", "Nothing", "can", "distract", "me"], "sentenceWordChoices": ["distract", "me", "locked", "Anything", "Nothing", "can", "locking", "Totally", "in", "distracts"]}, {"sentenceText": "Not yet. I''m finally locked in, so don''t jinx it.", "highlightingPart": "locked in", "sentenceTranslation": "아직. 겨우 몰입했으니까 초 치지 마.", "practiceQuestion": "You''ve been at that desk all day. Break time?", "practiceQuestionTranslation": "하루 종일 책상에 있네. 쉬는 시간 어때?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/644/practice-examples/91ce3e0e-3d5c-4e17-bf40-448a510279d8.webp", "sentenceWords": ["Not", "yet", "I''m", "finally", "locked", "in", "so", "don''t", "jinx", "it"], "sentenceWordChoices": ["don''t", "jinx", "doesn''t", "Not", "yet", "finally", "in", "I''m", "locked", "so", "jinxed", "lock", "it"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0106201172,0.0082244873,-0.0797119141,-0.0117721558,0.0166931152,0.00185585022,0.0313720703,0.040802002,-0.0399475098,-0.0420837402,0.013130188,0.0317382812,0.0207061768,0.0176849365,0.00917053223,-0.0401916504,-0.0697021484,-0.0190887451,-9.66191292e-05,0.00408172607,0.00260162354,-0.0121688843,0.0138778687,0.0494995117,-0.0219421387,0.0357971191,-0.0165100098,-0.0307159424,0.040802002,0.0223083496,-0.0337219238,-0.0294952393,0.0104904175,-0.0547485352,0.0096282959,-0.0527954102,0.0118637085,0.0233612061,-0.0239715576,-0.0425415039,0.00821685791,-0.0563659668,0.0109405518,0.0240020752,0.0214996338,0.00726699829,0.00674057007,-0.0233306885,0.00276565552,0.0265197754,0.00981903076,0.0211791992,-0.0204315186,0.00521850586,-0.0274658203,-0.0380249023,0.0377502441,0.0269470215,0.0407409668,-0.0246124268,0.0330505371,-0.0106124878,0.0309143066,0.0623779297,0.0220794678,-0.0589294434,-