(682,NULL,'RELATIONSHIP_SOCIAL','BASIC','EN','KR',519,'mingle','(모임에서) 이리저리 어울리다','파티에서 섞이기 mingle','파티나 모임에서 한자리에 붙어 있지 않고 여기저기 돌아다니며 여러 사람과 가볍게 대화하는 것을 말한다. 원래 "섞이다"라는 뜻이라, 사람들 사이에 자연스럽게 섞여 드는 그림이다. 호스트가 "Go mingle!" 하고 등을 떠밀거나, 낯가리는 사람이 "I''m bad at mingling"이라고 할 때 자주 나온다.','Why are you hiding in the kitchen at your own party?','네 파티인데 왜 부엌에 숨어 있어?','I should go mingle instead of talking to you all night.','밤새 너랑만 얘기하지 말고 가서 좀 섞여야겠다.',ARRAY['I','should','go','mingle','instead','of','talking','to','you','all','night']::varchar[],ARRAY['I','go','mingles','of','mingle','talking','should','nights','you','all','to','night','talk','instead']::varchar[],NULL,'[{"sentenceText": "Fine, I''ll go mingle for ten minutes.", "highlightingPart": "mingle", "sentenceTranslation": "알았어, 딱 10분만 돌면서 어울려 볼게.", "practiceQuestion": "Are you just going to stand by the snack table?", "practiceQuestionTranslation": "너 그냥 간식 테이블 앞에만 서 있을 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/682/practice-examples/9826d6c5-8d55-405d-b332-2c02f592df86.webp", "sentenceWords": ["Fine", "I''ll", "go", "mingle", "for", "ten", "minutes"], "sentenceWordChoices": ["go", "mingles", "since", "minute", "ten", "mingle", "for", "minutes", "Fine", "I''ll"]}, {"sentenceText": "Exhausting. I mingled with like thirty strangers.", "highlightingPart": "mingled", "sentenceTranslation": "진 빠지더라. 모르는 사람 서른 명이랑 어울렸다니까.", "practiceQuestion": "How was the networking event?", "practiceQuestionTranslation": "네트워킹 행사는 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/682/practice-examples/0e63c123-7e65-4c0d-8bcc-28cc34ba3ece.webp", "sentenceWords": ["Exhausting", "I", "mingled", "with", "like", "thirty", "strangers"], "sentenceWordChoices": ["thirty", "strangers", "like", "mingles", "stranger", "mingled", "Exhausting", "I", "within", "with"]}, {"sentenceText": "She''s mingling somewhere in the crowd.", "highlightingPart": "mingling", "sentenceTranslation": "저 사람들 틈 어딘가에서 돌아다니고 있을걸.", "practiceQuestion": "Where''s the host? I wanted to say hi.", "practiceQuestionTranslation": "호스트 어디 갔어? 인사하고 싶었는데.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/682/practice-examples/0e73d8ba-a690-4acd-85c6-ad4397ea1b5e.webp", "sentenceWords": ["She''s", "mingling", "somewhere", "in", "the", "crowd"], "sentenceWordChoices": ["crowds", "mingling", "somewhere", "crowd", "She''s", "in", "mingle", "the", "anywhere"]}, {"sentenceText": "Mostly to mingle and meet people before classes start.", "highlightingPart": "mingle", "sentenceTranslation": "개강 전에 사람들이랑 어울리면서 얼굴 트라고 하는 거지.", "practiceQuestion": "What''s the point of orientation week?", "practiceQuestionTranslation": "오리엔테이션 주간은 왜 하는 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/682/practice-examples/285ae025-880a-4640-ab3d-7a61d98fd91f.webp", "sentenceWords": ["Mostly", "to", "mingle", "and", "meet", "people", "before", "classes", "start"], "sentenceWordChoices": ["meet", "classes", "Mostly", "starts", "to", "mingles", "met", "people", "start", "and", "mingle", "before"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[-0.0103149414,-0.0346374512,-0.0265197754,-0.00277709961,-0.0111923218,-0.0322265625,-0.0066986084,0.0526733398,-0.00582504272,0.00219345093,-0.0410461426,-0.00326538086,0.0341796875,0.0288391113,-0.0296325684,0.000669002533,-0.0510864258,0.0191497803,0.0312042236,-0.00853729248,0.00102519989,-0.00729370117,0.00632476807,0.0327148438,-0.0286865234,0.0338439941,-0.0232391357,0.0364685059,0.00372123718,0.00559997559,-0.00778198242,-0.0296936035,0.0124435425,-0.0718383789,0.019744873,0.00417709351,-0.0108642578,0.0217437744,-0.0379638672,-0.0747680664,0.00426864624,-0.00587463379,0.0246582031,0.00826263428,0.06640625,0.0184936523,0.0125579834,-0.0383300781,0.0550231934,0.0214996338,0.00161075592,-0.00803375244,-0.0249633789,0.0264434814,-0.00999450684,-0.0282897949,0.0102233887,-0.016708374,0.0216217041,-0.00605010986,0.0217590332,0.0