(685,NULL,'WORK_STUDY','CLASSIC_COMMON','EN','KR',522,'burn the midnight oil','밤늦게까지 일하다, 공부하다','밤샘 각 burn the midnight oil','전기가 없던 시절 밤에 등잔 기름을 태워 가며 일하던 데서 온 고전 관용구다. 시험 공부든 야근이든, 자정 넘어서까지 책상 앞에 붙어 있는 상황을 묘사할 때 쓴다. 오래된 표현이지만 지금도 누구나 알아듣고, 격식·비격식 어디서나 무난하다.','Why do you have three coffees on your desk?','책상에 커피가 왜 세 잔이나 있어?','I''ll be burning the midnight oil to finish this paper.','이 페이퍼 끝내려면 밤늦게까지 달려야 해.',ARRAY['I''ll','be','burning','the','midnight','oil','to','finish','this','paper']::varchar[],ARRAY['midnight','burning','finish','oil','to','burn','I''ll','this','the','be','paper','oils','finished']::varchar[],NULL,'[{"sentenceText": "Yeah, I burned the midnight oil studying for finals.", "highlightingPart": "burned the midnight oil", "sentenceTranslation": "응, 기말 공부하느라 밤늦게까지 불태웠어.", "practiceQuestion": "You look exhausted. Rough night?", "practiceQuestionTranslation": "너 완전 피곤해 보인다. 밤에 무슨 일 있었어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/685/practice-examples/fbd1aa2f-5a5b-49eb-9faf-a2c13bdb8be6.webp", "sentenceWords": ["Yeah", "I", "burned", "the", "midnight", "oil", "studying", "for", "finals"], "sentenceWordChoices": ["Yeah", "study", "the", "studying", "final", "oil", "midnight", "burn", "I", "for", "burned", "finals"]}, {"sentenceText": "Everyone burned the midnight oil for two straight weeks.", "highlightingPart": "burned the midnight oil", "sentenceTranslation": "다들 2주 내내 야근하면서 갈아 넣었지.", "practiceQuestion": "How did your team ship the app on time?", "practiceQuestionTranslation": "너희 팀은 어떻게 제때 앱을 출시했어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/685/practice-examples/53ffd7cb-f3c4-4db3-9f78-9f328f082d8e.webp", "sentenceWords": ["Everyone", "burned", "the", "midnight", "oil", "for", "two", "straight", "weeks"], "sentenceWordChoices": ["since", "weeks", "midnight", "two", "oil", "Everyone", "the", "for", "straight", "burned", "burn", "week"]}, {"sentenceText": "Can''t. I''m burning the midnight oil on this report.", "highlightingPart": "burning the midnight oil", "sentenceTranslation": "안 돼. 이 보고서 때문에 밤샘 각이야.", "practiceQuestion": "Want to watch a movie tonight?", "practiceQuestionTranslation": "오늘 밤에 영화 볼래?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/685/practice-examples/4ac2f40b-ca87-4ecf-99d0-8812fc6b986c.webp", "sentenceWords": ["Can''t", "I''m", "burning", "the", "midnight", "oil", "on", "this", "report"], "sentenceWordChoices": ["I''m", "the", "midnight", "burn", "oil", "Can''t", "on", "burning", "this", "reports", "report", "at"]}, {"sentenceText": "Always. He burns the midnight oil almost every night.", "highlightingPart": "burns the midnight oil", "sentenceTranslation": "맨날 그래. 거의 매일 밤늦게까지 뭘 해.", "practiceQuestion": "Is your roommate still up at 3 a.m.?", "practiceQuestionTranslation": "네 룸메 새벽 3시에도 안 자?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/685/practice-examples/becc1585-3be0-47b4-9d33-7efc273b2760.webp", "sentenceWords": ["Always", "He", "burns", "the", "midnight", "oil", "almost", "every", "night"], "sentenceWordChoices": ["oil", "almost", "the", "Always", "night", "every", "oils", "midnight", "burn", "burns", "nights", "He"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00933837891,-0.00468826294,-0.0162963867,-0.0694580078,-0.000248193741,-0.0198516846,0.0336303711,0.0461730957,0.015625,-0.03125,0.0166015625,-0.000803470612,-0.00468063354,-0.0229187012,0.0317993164,0.0294189453,-0.0222015381,0.000134825706,0.006275177,0.00650024414,0.0371398926,-0.0419006348,-0.0367736816,0.0447387695,-0.0121002197,0.0429382324,-0.0141983032,0.0215911865,0.018951416,-0.00373077393,-0.0307922363,-0.0401916504,0.0391845703,-0.0532531738,0.00680160522,-0.0275268555,0.0207672119,-0.0199737549,-0.012550354,-0.0689086914,-0.0102386475,-0.0593261719,0.0419616699,-0.0069770813,0.0251464844,0.00156974792,0.0142822266,-0.000398159027,0.0881958008,0.0377807617,0.0123977661,0.0162200928,0.00534439087,0.0163