(695,NULL,'RELATIONSHIP_SOCIAL','SLANG_NEOLOGISM','EN','KR',532,'regift','(받은 선물을) 되선물하다','선물 돌려막기 regift','받았지만 쓰지 않는 선물을 포장만 바꿔 다른 사람에게 다시 선물하는 것을 뜻하는 신조어다. 시트콤 사인펠드에서 퍼진 말로, 이제는 사전에도 오른 일상 단어가 됐다. 들키면 민망한 행동이라, 보통 들켰거나 의심받는 웃긴 상황에서 등장한다.','This candle looks exactly like the one I gave you last year.','이 캔들, 작년에 내가 너한테 준 거랑 똑같이 생겼는데.','Did you seriously regift the mug I gave you?','내가 준 머그컵을 진짜로 딴 사람한테 돌린 거야?',ARRAY['Did','you','seriously','regift','the','mug','I','gave','you']::varchar[],ARRAY['the','you','given','I','Did','mug','you','seriously','regift','gave','regifted','serious']::varchar[],NULL,'[{"sentenceText": "Don''t judge me, but I''m regifting this wine set.", "highlightingPart": "regifting", "sentenceTranslation": "뭐라 하지 마, 이 와인 세트 되선물할 거야.", "practiceQuestion": "What are you getting Marco for his birthday?", "practiceQuestionTranslation": "마르코 생일 선물 뭐 줄 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/695/practice-examples/aaf612ea-0e03-4eee-9a8c-c898cdb2af51.webp", "sentenceWords": ["Don''t", "judge", "me", "but", "I''m", "regifting", "this", "wine", "set"], "sentenceWordChoices": ["me", "judges", "but", "this", "set", "regifting", "regift", "judge", "Don''t", "I''m", "wine", "sets"]}, {"sentenceText": "It''s my regift stash for emergencies.", "highlightingPart": "regift", "sentenceTranslation": "급할 때 쓸 되선물용 비축템이거든.", "practiceQuestion": "Why do you keep that ugly sweater in the closet?", "practiceQuestionTranslation": "그 못생긴 스웨터는 왜 옷장에 계속 두는 거야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/695/practice-examples/07ad745d-0ac2-46d5-af34-72eba9f1c0e2.webp", "sentenceWords": ["It''s", "my", "regift", "stash", "for", "emergencies"], "sentenceWordChoices": ["for", "It''s", "regifts", "stash", "regift", "emergencies", "mine", "my"]}, {"sentenceText": "Regifting is fine as long as you don''t get caught.", "highlightingPart": "Regifting", "sentenceTranslation": "되선물은 안 들키기만 하면 괜찮아.", "practiceQuestion": "Is regifting rude, or is it just recycling?", "practiceQuestionTranslation": "되선물은 실례일까, 아니면 그냥 재활용일까?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/695/practice-examples/61f2e63b-7055-4401-b027-b40c37191c93.webp", "sentenceWords": ["Regifting", "is", "fine", "as", "long", "as", "you", "don''t", "get", "caught"], "sentenceWordChoices": ["fine", "as", "is", "as", "regift", "gifting", "don''t", "get", "you", "catch", "Regifting", "long", "caught"]}, {"sentenceText": "He regifted it with the original card still inside.", "highlightingPart": "regifted", "sentenceTranslation": "되선물하면서 원래 카드를 안 빼고 줬거든.", "practiceQuestion": "How did she find out about the scarf?", "practiceQuestionTranslation": "걔가 스카프 건은 어떻게 알아챘대?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/695/practice-examples/7f2ba278-0268-4e2c-a0e9-a84e184ed6e0.webp", "sentenceWords": ["He", "regifted", "it", "with", "the", "original", "card", "still", "inside"], "sentenceWordChoices": ["with", "originally", "inside", "still", "the", "it", "insides", "He", "original", "regift", "card", "regifted"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0463562012,0.0100860596,-0.0599365234,0.00505065918,-0.00161838531,-0.000637531281,-0.0324401855,0.0579223633,-0.00965881348,-0.0180511475,0.00782775879,-0.0059928894,0.0172119141,-0.0313415527,0.0152893066,0.0260467529,0.000507831573,-0.0288543701,-0.0185089111,0.0663452148,0.00682067871,0.016494751,0.0315246582,0.00927734375,0.0168914795,0.0396728516,-0.00633621216,0.0159454346,0.0776977539,0.0211334229,0.0221710205,-0.0287017822,0.0240783691,-0.0452270508,0.0322875977,0.041229248,0.00254058838,-0.00955200195,-0.0308227539,-0.0169677734,-0.0277404785,-0.0112686157,0.0302429199,-0.0131454468,0.0449523926,0.0962524414,0.00444030762,-0.00903320312,-1.48415565e-05,0.063293457,0.00886535645,0.0266113281,-0.0134506226,0.0231323242,-0.0292205811,-0.00960540771,0.0105438232,0.00346755981,-0.00242996216,-0.0237121582,-0.027969