(736,NULL,'EMOTION_EMPATHY','BASIC','EN','KR',573,'pleasantly surprised','기분 좋게 놀란, 기대 이상인','기분 좋은 반전 pleasantly surprised','기대를 별로 안 했는데 생각보다 좋아서 놀랐을 때 쓰는 표현이다. "I was pleasantly surprised by ~" 형태로 쓰며, 낮았던 기대와 대비되는 만족을 담아 리뷰의 단골 문장이 됐다. 대놓고 극찬은 아니지만 진심이 느껴지는 은근한 호평이다.','Weren''t you worried about the low ratings?','평점 낮아서 걱정하지 않았어?','I was, but I was pleasantly surprised.','걱정했지, 근데 기대 이상이더라.',ARRAY['I','was','but','I','was','pleasantly','surprised']::varchar[],ARRAY['surprising','was','I','I','but','were','surprised','pleasant','pleasantly','was']::varchar[],NULL,'[{"sentenceText": "Pleasantly surprised, honestly. The pasta was solid.", "highlightingPart": "Pleasantly surprised", "sentenceTranslation": "솔직히 기대 이상이었어. 파스타 괜찮더라.", "practiceQuestion": "How was the dorm cafeteria''s new menu?", "practiceQuestionTranslation": "기숙사 식당 새 메뉴 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/736/practice-examples/e99846c5-44ea-4886-b5ef-f8b8c518d13d.webp", "sentenceWords": ["Pleasantly", "surprised", "honestly", "The", "pasta", "was", "solid"], "sentenceWordChoices": ["pasta", "surprising", "Pleasant", "surprised", "The", "honest", "honestly", "was", "solid", "Pleasantly"]}, {"sentenceText": "I was pleasantly surprised by the legroom.", "highlightingPart": "pleasantly surprised", "sentenceTranslation": "좌석 간격이 생각보다 좋아서 놀랐어.", "practiceQuestion": "Did the budget airline treat you okay?", "practiceQuestionTranslation": "그 저가 항공사 탈 만했어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/736/practice-examples/f7c4718f-c56e-4620-857d-e3616ce72e89.webp", "sentenceWords": ["I", "was", "pleasantly", "surprised", "by", "the", "legroom"], "sentenceWordChoices": ["surprising", "surprised", "pleasantly", "I", "pleasant", "legroom", "were", "the", "by", "was"]}, {"sentenceText": "Not at all. Pleasantly surprised is an understatement.", "highlightingPart": "Pleasantly surprised", "sentenceTranslation": "전혀. 기분 좋게 놀랐다는 말로도 부족해.", "practiceQuestion": "Were you expecting that grade on the essay?", "practiceQuestionTranslation": "에세이 그 점수 예상했어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/736/practice-examples/f76f871d-1ef2-4f01-82de-d9ae7eeb74d8.webp", "sentenceWords": ["Not", "at", "all", "Pleasantly", "surprised", "is", "an", "understatement"], "sentenceWordChoices": ["overstatement", "surprising", "surprised", "Not", "is", "understatement", "all", "Pleasantly", "an", "at", "Pleasant"]}, {"sentenceText": "She''ll be pleasantly surprised, trust me.", "highlightingPart": "pleasantly surprised", "sentenceTranslation": "기대 이상이라고 좋아하실 거야, 믿어봐.", "practiceQuestion": "Think Mom will like the gift we picked?", "practiceQuestionTranslation": "엄마가 우리가 고른 선물 좋아하실까?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/736/practice-examples/e97f06b1-fe56-4bf5-b934-ba1245bc112f.webp", "sentenceWords": ["She''ll", "be", "pleasantly", "surprised", "trust", "me"], "sentenceWordChoices": ["pleasant", "pleasantly", "She''ll", "trust", "surprised", "be", "trusted", "surprising", "me"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.046081543,-0.0483093262,-0.116821289,0.0439147949,-0.0100860596,-0.0156402588,-0.0153579712,0.0114974976,0.00315284729,-0.0194244385,-0.0112304688,-0.0387268066,0.0339050293,0.00897979736,0.0465698242,0.0346984863,-0.0213928223,0.00736618042,-0.0101928711,-0.00466918945,0.0124893188,-0.0140533447,-0.00407028198,0.00189495087,0.00759887695,0.00994873047,-0.0223846436,0.00852966309,0.0320739746,-0.0205993652,0.00740432739,-0.0259094238,0.0252075195,-0.0436096191,0.027053833,0.029083252,-0.0218963623,-0.0262298584,-0.00963592529,-0.0319519043,0.022064209,-0.0143661499,0.00726318359,0.0195617676,0.0149688721,0.0158996582,-0.0103912354,0.0130310059,-0.0299377441,0.0302276611,0.00778961182,0.0308532715,-0.0061378479,0.0407409668,-0.00527572632,-0.0123214722,-0.00370788574,-0.0118179321,0.00163459778,-0.0412597656,0.0309753418,-0.0325317383,0.01568603