(745,NULL,'EMOTION_EMPATHY','SLANG_NEOLOGISM','EN','KR',582,'crush it','끝내주게 잘 해내다','끝내주게 해냈다 crush it','시험, 발표, 공연 등을 압도적으로 잘 해냈다는 뜻의 캐주얼한 표현이다. 특히 "you crushed it!"은 뭔가를 마치고 온 상대에게 던지는 단골 칭찬 리액션으로, "완전 잘했어!", "끝내줬어!" 정도의 느낌이다. 으깨버릴(crush) 만큼 압도했다는 어감이라 친구 사이 응원과 축하에 잘 어울린다.','I just finished my last exam of the semester!','방금 이번 학기 마지막 시험 끝냈어!','I''m sure you crushed it! Let''s celebrate tonight.','분명 완전 잘 봤을 거야! 오늘 밤 축하하자.',ARRAY['I''m','sure','you','crushed','it','Let''s','celebrate','tonight']::varchar[],ARRAY['crushed','surely','you','sure','Let''s','tonight','it','crashed','celebrate','I''m','celebrated']::varchar[],NULL,'[{"sentenceText": "You crushed it. Everyone was totally engaged.", "highlightingPart": "crushed it", "sentenceTranslation": "끝내줬어. 다들 완전 집중하더라.", "practiceQuestion": "How was my first time hosting the club meeting?", "practiceQuestionTranslation": "내가 처음 진행한 동아리 모임 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/745/practice-examples/1004c146-5786-4f90-8838-43800f24bac9.webp", "sentenceWords": ["You", "crushed", "it", "Everyone", "was", "totally", "engaged"], "sentenceWordChoices": ["crashed", "it", "engaged", "totally", "Everyone", "were", "was", "You", "crushed", "total"]}, {"sentenceText": "Not really. We''ve been practicing all month, so we''ll crush it.", "highlightingPart": "crush it", "sentenceTranslation": "별로. 한 달 내내 연습했으니까 우리가 씹어먹을 거야.", "practiceQuestion": "Are you worried about the coding competition?", "practiceQuestionTranslation": "코딩 대회 걱정돼?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/745/practice-examples/9034a4b0-950c-44af-ad16-cc93ea6b2670.webp", "sentenceWords": ["Not", "really", "We''ve", "been", "practicing", "all", "month", "so", "we''ll", "crush", "it"], "sentenceWordChoices": ["month", "practicing", "crushed", "really", "we''ll", "been", "We''ve", "crush", "it", "months", "all", "so", "Not", "practiced"]}, {"sentenceText": "Passed? He crushed it with a perfect score.", "highlightingPart": "crushed it", "sentenceTranslation": "붙은 정도가 아니라 만점으로 뚫었어.", "practiceQuestion": "Did your roommate pass his driving test?", "practiceQuestionTranslation": "너네 룸메 운전면허 시험 붙었대?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/745/practice-examples/3c17d8b3-cbd8-46f5-a51c-bd692e89bb30.webp", "sentenceWords": ["Passed", "He", "crushed", "it", "with", "a", "perfect", "score"], "sentenceWordChoices": ["it", "Past", "crushed", "He", "Passed", "crashed", "a", "scores", "score", "perfect", "with"]}, {"sentenceText": "One quiz is nothing. You''ll crush the final.", "highlightingPart": "crush the final", "sentenceTranslation": "퀴즈 하나쯤이야. 기말은 네가 씹어먹을 거야.", "practiceQuestion": "I bombed the quiz even though I studied.", "practiceQuestionTranslation": "공부했는데도 퀴즈 망했어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/745/practice-examples/89946b62-9959-4d36-8906-74939505aaa4.webp", "sentenceWords": ["One", "quiz", "is", "nothing", "You''ll", "crush", "the", "final"], "sentenceWordChoices": ["anything", "quiz", "crush", "You''ll", "is", "the", "final", "One", "crushed", "quizzes", "nothing"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00869750977,0.0316467285,-0.0656738281,0.00604629517,0.0102996826,-0.0271606445,0.0198669434,0.00562667847,0.00793457031,0.0102005005,0.0145721436,0.0292663574,-0.0116195679,-0.0380859375,-0.00259399414,-0.0301055908,-0.00459671021,0.0111694336,0.0525512695,-0.016418457,0.0374450684,-0.0153808594,0.010848999,0.000745296478,-0.0136871338,0.0491027832,0.000605106354,0.0282440186,0.0527038574,-0.00705337524,-0.0225982666,-0.0190582275,-0.0149612427,-0.0489501953,0.0243835449,-0.0227508545,0.0133743286,0.0280456543,-0.00598526001,0.0120315552,0.0527038574,-0.00968170166,0.0666503906,-0.00074005127,-0.0105285645,0.00571060181,-0.0215911865,0.00417327881,0.0296630859,0.0372619629,0.0189819336,0.0325317383,-0.00545120239,0.0693359375,-0.0254364014,0.00387763977,0.0168914795,0.0