(781,NULL,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',618,'big time','제대로, 심하게','제대로 강조 big time','문장 끝에 붙여 "제대로, 심하게"라고 정도를 강조하는 부사구다. 좋은 일 나쁜 일 가리지 않고 쓰이며, I owe you big time처럼 "크게 신세 졌다"는 관용 표현으로도 자주 나온다. 캐주얼한 구어체라 격식 있는 글에는 어울리지 않는다.','How did the presentation go?','발표 어떻게 됐어?','I messed up big time.','나 제대로 망했어.',ARRAY['I','messed','up','big','time']::varchar[],ARRAY['bigger','messed','times','I','big','time','messes','up']::varchar[],NULL,'[{"sentenceText": "Finals hit me big time this week.", "highlightingPart": "big time", "sentenceTranslation": "이번 주 기말고사에 제대로 당했어.", "practiceQuestion": "You look exhausted. What happened?", "practiceQuestionTranslation": "너 완전 지쳐 보인다. 무슨 일 있었어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/781/practice-examples/e587e4b8-6066-4dd3-8848-7276aaef667b.webp", "sentenceWords": ["Finals", "hit", "me", "big", "time", "this", "week"], "sentenceWordChoices": ["this", "times", "week", "bigger", "big", "Finals", "hits", "time", "hit", "me"]}, {"sentenceText": "Yeah, I owe him big time.", "highlightingPart": "big time", "sentenceTranslation": "응, 걔한테 크게 신세 졌지.", "practiceQuestion": "Did your roommate help you move in?", "practiceQuestionTranslation": "룸메가 이사 도와줬어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/781/practice-examples/ca9bfebe-ad34-42b4-b5b5-c9022f24a6fd.webp", "sentenceWords": ["Yeah", "I", "owe", "him", "big", "time"], "sentenceWordChoices": ["I", "Yeah", "times", "bigger", "big", "owe", "him", "owes", "time"]}, {"sentenceText": "Big time. They lost three games straight.", "highlightingPart": "Big time", "sentenceTranslation": "제대로지. 3연패 했잖아.", "practiceQuestion": "Is the team missing their captain?", "practiceQuestionTranslation": "그 팀 주장 빠져서 티 나?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/781/practice-examples/4b11dd79-2f99-4921-a480-9cc116f7a647.webp", "sentenceWords": ["Big", "time", "They", "lost", "three", "games", "straight"], "sentenceWordChoices": ["times", "They", "loses", "lost", "three", "time", "bigger", "straight", "games", "Big"]}, {"sentenceText": "Big time. We stayed in the hostel all day.", "highlightingPart": "Big time", "sentenceTranslation": "심하게. 하루 종일 호스텔에만 있었어.", "practiceQuestion": "Did the rain mess up your trip?", "practiceQuestionTranslation": "비 와서 여행 망쳤어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/781/practice-examples/b321d863-7fd2-4777-9724-bd972a533b27.webp", "sentenceWords": ["Big", "time", "We", "stayed", "in", "the", "hostel", "all", "day"], "sentenceWordChoices": ["all", "times", "We", "day", "time", "stays", "Big", "bigger", "the", "stayed", "hostel", "in"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00458526611,-0.0366821289,-0.00964355469,0.0310516357,-0.0499572754,0.0118408203,-0.0198516846,0.0284118652,-0.0344238281,-0.00163459778,0.050201416,-0.0202026367,-0.00689697266,-0.015335083,0.0450744629,0.0246429443,-0.0759277344,-0.0226135254,0.0545349121,0.0149383545,-0.0152206421,0.0204467773,0.019821167,0.0737304688,0.0200500488,0.0251464844,-0.00811004639,0.0684814453,0.0912475586,0.0123672485,0.0103225708,-0.0415344238,0.0548400879,-0.0452575684,-0.0204620361,0.000813484192,0.00510787964,0.042175293,0.0139007568,-0.058013916,0.0426330566,-0.00392532349,0.0165405273,-0.000173330307,0.0192718506,0.02394104,-0.0317077637,0.00815582275,0.0036315918,0.0607299805,-0.00862884521,0.0276031494,-0.004737854,0.0650024414,0.0188751221,-0.010887146,0.00993347168,0.0494689941,0.0641479492,-0.0498046875,-0.00705337524,0.00146770477,0.0415649414,0.0181274414,-0.044921875,-0.00484085083,-0.0093536377,0.0244598389,0.0116577148,0.0142669678,-0.00282096863,-0.0310821533,-0.0239562988,-0.0180358887,0.0531005859,0.0252227783,-0.0308227539,0.020324707,-0.00238227844,-0.0314941406,0.0353088379,-0.0181427002,-0.0249023438,0.0525817871,-0.00818634033,-0.0347595215,-0.0619812012,-0.0138778687,0.0072555542,0.0148544312,0.0405883789,0.0584716797,0.0195617676