(795,NULL,'CONVERSATION_SKILL','BASIC','EN','KR',632,'believe it or not','믿기 힘들겠지만','놀람 예고 believe it or not','놀랍거나 의외인 사실을 말하기 전에 붙이는 완충구로, "믿거나 말거나", 즉 "믿기 힘들겠지만"이라는 뜻이다. 듣는 사람의 놀람을 미리 예고해 이야기에 긴장감을 주는 효과가 있다. 보통 문장 맨 앞에 둔다.','Did you finish the whole assignment last night?','어젯밤에 과제 다 끝냈어?','Believe it or not, I finished it in two hours.','믿기 힘들겠지만 두 시간 만에 끝냈어.',ARRAY['Believe','it','or','not','I','finished','it','in','two','hours']::varchar[],ARRAY['finished','hours','it','finish','in','Believe','two','or','not','I','Believing','it','hour']::varchar[],NULL,'[{"sentenceText": "Believe it or not, we met just last month.", "highlightingPart": "Believe it or not", "sentenceTranslation": "믿기 힘들겠지만 지난달에 처음 만났어.", "practiceQuestion": "Have you two known each other long?", "practiceQuestionTranslation": "너네 둘 안 지 오래됐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/795/practice-examples/fba11289-37e4-4910-8fa4-e50fe982be9e.webp", "sentenceWords": ["Believe", "it", "or", "not", "we", "met", "just", "last", "month"], "sentenceWordChoices": ["not", "it", "meet", "Believing", "Believe", "or", "months", "we", "last", "month", "met", "just"]}, {"sentenceText": "Believe it or not, the freshman who burned rice last week.", "highlightingPart": "Believe it or not", "sentenceTranslation": "안 믿기겠지만, 지난주에 밥 태운 그 신입생.", "practiceQuestion": "Who won the cooking contest?", "practiceQuestionTranslation": "요리 대회 누가 우승했어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/795/practice-examples/eb611398-3ab3-40b6-bdc5-2bbceeb7fa12.webp", "sentenceWords": ["Believe", "it", "or", "not", "the", "freshman", "who", "burned", "rice", "last", "week"], "sentenceWordChoices": ["freshmen", "Believe", "who", "Believing", "last", "burns", "or", "freshman", "week", "burned", "it", "not", "rice", "the"]}, {"sentenceText": "Believe it or not, under a hundred bucks.", "highlightingPart": "Believe it or not", "sentenceTranslation": "믿기 힘들겠지만 100달러도 안 했어.", "practiceQuestion": "How much was your flight?", "practiceQuestionTranslation": "비행기표 얼마였어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/795/practice-examples/ec364b9d-3f45-413a-9fbf-0c0a775e1c4b.webp", "sentenceWords": ["Believe", "it", "or", "not", "under", "a", "hundred", "bucks"], "sentenceWordChoices": ["Believe", "over", "buck", "hundred", "Believing", "or", "it", "bucks", "not", "a", "under"]}, {"sentenceText": "Believe it or not, every single day.", "highlightingPart": "Believe it or not", "sentenceTranslation": "안 믿기겠지만, 하루도 안 빼먹어.", "practiceQuestion": "Does your roommate really wake up at five?", "practiceQuestionTranslation": "네 룸메 진짜 5시에 일어나?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/795/practice-examples/edaa637b-7ecf-43ab-bffa-42495e49c19a.webp", "sentenceWords": ["Believe", "it", "or", "not", "every", "single", "day"], "sentenceWordChoices": ["Believe", "not", "single", "every", "it", "Believing", "or", "days", "day"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00400543213,-0.0428771973,-0.125,0.0238037109,-0.010269165,-0.0336914062,-0.0223846436,-0.0112075806,0.00360298157,-0.000838756561,-0.0310974121,-0.00957489014,0.0298614502,0.0281677246,0.0205078125,0.0262451172,-0.0618286133,0.00252151489,-0.00380516052,0.00226402283,0.0216674805,0.012336731,-0.0235290527,0.0136260986,0.00729370117,0.0151062012,-0.000570297241,-0.00859832764,0.029586792,0.00841522217,0.019821167,-0.0411376953,0.0213775635,-0.0466918945,-0.018951416,0.0447692871,0.0542602539,-0.052520752,0.0145492554,-0.0641479492,0.00759887695,-0.0365600586,0.0673828125,0.0328979492,0.0249786377,0.0580444336,-0.00749588013,-0.000172376633,-0.00484085083,0.00907897949,-0.000877857208,0.015045166,-0.00670623779,0.0351867676,-0.0412597656,0.00240135193,-0.00518417358,0.0133132935,-0.0389709473,-0.0729370117,0.0361022949,-0.0526733398,0.0406188965,0.0555725098,0.000235676765,-0.0176086426,0.00776672363,0.0151596069,-0.040802002,0.0591735