(811,NULL,'CONVERSATION_SKILL','CLASSIC_COMMON','EN','KR',648,'drumroll(, please)','두구두구 (발표 직전 효과)','발표 직전 효과음 drumroll, please','순위나 결과를 발표하기 직전에 긴장감을 끌어올리는 익살 멘트다. 시상식에서 드럼을 두구두구 울리던 데서 온 표현으로, 한국어의 "두구두구"와 정확히 같은 역할을 한다. 소소한 발표를 일부러 거창하게 만들 때 쓰면 웃음 포인트가 된다.','So who won the bet? Don''t keep us waiting!','그래서 내기 누가 이겼어? 뜸 들이지 마!','And the winner is... drumroll, please... Chloe!','그리고 우승자는... 두구두구... 클로이!',ARRAY['And','the','winner','is','drumroll','please','Chloe']::varchar[],ARRAY['pleased','Chloe','drumrolls','winner','And','the','please','is','winners','drumroll']::varchar[],NULL,'[{"sentenceText": "Drumroll, please... we''re going to Tokyo!", "highlightingPart": "Drumroll, please", "sentenceTranslation": "두구두구... 우리 도쿄 간다!", "practiceQuestion": "Did you decide where we''re going for spring break?", "practiceQuestionTranslation": "봄방학에 어디 갈지 정했어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/811/practice-examples/712a4ecd-01cb-4f7a-aa27-9c9be0add010.webp", "sentenceWords": ["Drumroll", "please", "we''re", "going", "to", "Tokyo"], "sentenceWordChoices": ["Tokyo", "we''re", "please", "Drumrolls", "go", "going", "to", "pleased", "Drumroll"]}, {"sentenceText": "Drumroll... an A minus, baby!", "highlightingPart": "Drumroll", "sentenceTranslation": "두구두구... A 마이너스다, 야호!", "practiceQuestion": "So what did you get on the final?", "practiceQuestionTranslation": "그래서 기말 몇 점 받았어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/811/practice-examples/15972752-a7fc-4bce-bb45-86ab1a115081.webp", "sentenceWords": ["Drumroll", "an", "A", "minus", "baby"], "sentenceWordChoices": ["Drumrolls", "an", "Drumroll", "A", "baby", "minus", "babies"]}, {"sentenceText": "Okay, drumroll, please. I got the internship!", "highlightingPart": "drumroll, please", "sentenceTranslation": "좋아, 두구두구. 나 인턴 붙었어!", "practiceQuestion": "What''s the big news you''ve been teasing all day?", "practiceQuestionTranslation": "하루 종일 뜸 들이던 그 소식이 뭔데?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/811/practice-examples/0b32e2f5-c44e-48da-badd-53b872ce2eba.webp", "sentenceWords": ["Okay", "drumroll", "please", "I", "got", "the", "internship"], "sentenceWordChoices": ["I", "internship", "drumroll", "gets", "got", "the", "pleased", "Okay", "please", "drumrolls"]}, {"sentenceText": "Drumroll... the sushi place you''ve been dying to try.", "highlightingPart": "Drumroll", "sentenceTranslation": "두구두구... 네가 그렇게 가고 싶어 하던 스시집.", "practiceQuestion": "Which restaurant did you pick for my birthday?", "practiceQuestionTranslation": "내 생일에 갈 식당 어디로 골랐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/811/practice-examples/d9fdd753-d1de-4f85-b828-c21f715ec0dd.webp", "sentenceWords": ["Drumroll", "the", "sushi", "place", "you''ve", "been", "dying", "to", "try"], "sentenceWordChoices": ["Drumroll", "sushi", "dying", "Drumrolls", "tries", "to", "the", "place", "died", "you''ve", "been", "try"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.0679321289,-0.0245361328,-0.010093689,0.00625228882,-0.0251617432,0.0124053955,-0.00911712646,0.0225372314,-0.00945281982,0.0068321228,0.00338745117,-0.0050201416,0.00768280029,0.00884246826,0.0381469727,0.000435113907,-0.0855712891,0.0147247314,0.0333557129,-0.00608825684,0.0122299194,-0.0601196289,-0.0204315186,0.0357055664,0.0246276855,-0.0013256073,-0.0220031738,0.0468444824,0.0217590332,-0.0610656738,-0.0102767944,-0.0344238281,0.025177002,-0.0703125,-0.0579223633,0.019317627,-0.0146179199,0.0133056641,-0.0141143799,-0.0235595703,-0.0257873535,-0.0445556641,0.0125808716,0.00231170654,0.00674819946,0.0459899902,-0.0254821777,-0.0430603027,0.00533294678,0.0673217773,-0.017868042,0.00705718994,0.00159549713,0.0446166992,0.00371551514,-0.00517272949,0.0252990723,-0.0127334595,0.0458984375,-0.0695800781,0.00663375854,-0.0277709961,0.0189819336,-0.0215911865,-0.00621414185,-0.0137710571,-0.0197601318,0.0285491943,0.0383911133,0.037689209,-0.000675201416,