(919,NULL,'CONVERSATION_SKILL','CLASSIC_COMMON','EN','KR',756,'learn ~ the hard way','호되게 겪고 나서야 배우다','몸으로 배운 교훈 learn ~ the hard way','말로 들어서가 아니라 직접 실패를 겪고 나서야 뭔가를 깨달았다는 뜻이다. the hard way는 "힘든 방식으로", 즉 몸으로 부딪혀 배웠다는 발상이다. "I learned that the hard way"처럼 쓰며, 남에게 조언할 때 "나처럼 고생하지 말라"는 뉘앙스를 실을 수 있다.','Why do you always save your files twice?','너는 왜 항상 파일을 두 번씩 저장해?','I learned that the hard way last semester.','지난 학기에 호되게 겪고 배웠거든.',ARRAY['I','learned','that','the','hard','way','last','semester']::varchar[],ARRAY['hardly','ways','semester','the','learned','learn','way','hard','I','last','that']::varchar[],NULL,'[{"sentenceText": "I learned that lesson the hard way in Bangkok.", "highlightingPart": "learned that lesson the hard way", "sentenceTranslation": "방콕에서 몸으로 겪고 배웠어.", "practiceQuestion": "Why won''t you eat street oysters anymore?", "practiceQuestionTranslation": "왜 이제 길거리 굴은 안 먹어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/919/practice-examples/9cca852c-077a-4f94-bcc3-b410b3d4f375.webp", "sentenceWords": ["I", "learned", "that", "lesson", "the", "hard", "way", "in", "Bangkok"], "sentenceWordChoices": ["lesson", "lessons", "hard", "the", "in", "learn", "I", "hardly", "way", "learned", "that", "Bangkok"]}, {"sentenceText": "You''ll learn the hard way when the pop quiz hits.", "highlightingPart": "learn the hard way", "sentenceTranslation": "깜짝 퀴즈 맞아보면 뼈저리게 알게 될걸.", "practiceQuestion": "Is it really that bad to skip the reading?", "practiceQuestionTranslation": "읽기 과제 건너뛰는 게 그렇게 큰일이야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/919/practice-examples/7c43e57d-1729-437a-8199-f1bd64d09132.webp", "sentenceWords": ["You''ll", "learn", "the", "hard", "way", "when", "the", "pop", "quiz", "hits"], "sentenceWordChoices": ["hard", "hit", "the", "quiz", "hardly", "pop", "learned", "You''ll", "the", "hits", "when", "way", "learn"]}, {"sentenceText": "Because I learned the hard way that apps glitch.", "highlightingPart": "learned the hard way", "sentenceTranslation": "앱이 먹통 되는 걸 호되게 겪어봤거든.", "practiceQuestion": "Why do you always confirm reservations by phone?", "practiceQuestionTranslation": "너는 왜 항상 전화로 예약 확인해?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/919/practice-examples/2c1cebbe-f72b-4091-b020-4ae2c2a5e414.webp", "sentenceWords": ["Because", "I", "learned", "the", "hard", "way", "that", "apps", "glitch"], "sentenceWordChoices": ["I", "that", "apps", "learned", "way", "the", "glitches", "Because", "glitch", "hardly", "hard", "learn"]}, {"sentenceText": "Tell her now, before she learns it the hard way.", "highlightingPart": "learns it the hard way", "sentenceTranslation": "데어보고 알기 전에 지금 말해줘.", "practiceQuestion": "Should I tell her the stove handle gets hot?", "practiceQuestionTranslation": "걔한테 냄비 손잡이 뜨거워진다고 말해줄까?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/919/practice-examples/b8c5a20b-f2e7-48fd-9b48-106371443ba6.webp", "sentenceWords": ["Tell", "her", "now", "before", "she", "learns", "it", "the", "hard", "way"], "sentenceWordChoices": ["learn", "now", "tells", "hard", "way", "Tell", "hardly", "learns", "before", "the", "it", "her", "she"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[0.00133419037,-0.025100708,-0.0253295898,0.026763916,0.00727462769,-0.00968170166,-0.0033531189,0.0223999023,0.0060005188,0.0269165039,0.0292510986,0.0178375244,0.00797271729,-0.0386657715,0.0180358887,-0.00398254395,0.0114364624,0.00120162964,-0.00230407715,0.0180053711,0.0331420898,0.00238609314,0.0525817871,0.0385131836,0.0448303223,0.0140457153,0.0567626953,0.00712203979,0.0228729248,0.0244445801,0.0135498047,-0.0182647705,-0.000812530518,-0.0269165039,0.00861358643,0.018447876,0.00558853149,0.024810791,-0.0241394043,-0.0182800293,0.00269889832,-0.0443115234,0.00295257568,0.0365905762,0.0400695801,0.0464782715,-0.0270385742,0.0160064697,0.0358886719,0.0493469238,-0.0319213867,0.0594177246,0.00882720947,0.0565185547,-0.0446777344,-