(924,NULL,'CONVERSATION_SKILL','CLASSIC_COMMON','EN','KR',761,'come again?','뭐라고요? 다시 말해줄래요?','정중한 되묻기 come again?','상대 말을 못 들었거나, 들었는데 믿기지 않아서 다시 말해달라고 할 때 쓰는 표현이다. "다시 와줄래?"가 아니라 "다시 말해줄래?"라는 뜻으로, what?보다 부드럽고 살짝 익살스러운 느낌이 있다. 놀람을 담아 "방금 뭐라고 하셨죠?" 하는 뉘앙스로도 자주 쓴다.','I said I''m moving to Alaska next month.','다음 달에 알래스카로 이사 간다고 했잖아.','Come again? Did you say Alaska?','뭐라고? 알래스카라고 했어?',ARRAY['Come','again','Did','you','say','Alaska']::varchar[],ARRAY['you','against','said','Alaska','say','Come','Did','comes','again']::varchar[],NULL,'[{"sentenceText": "Come again? Twenty percent?", "highlightingPart": "Come again", "sentenceTranslation": "뭐라고요? 20퍼센트요?", "practiceQuestion": "The rent is going up 20 percent.", "practiceQuestionTranslation": "월세가 20퍼센트 오른대.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/924/practice-examples/ec97062f-5453-4ce2-8298-68af92e60ef1.webp", "sentenceWords": ["Come", "again", "Twenty", "percent"], "sentenceWordChoices": ["percents", "comes", "Come", "Twenty", "again", "against", "percent"]}, {"sentenceText": "Come again? I haven''t even started.", "highlightingPart": "Come again", "sentenceTranslation": "뭐라고? 나 시작도 안 했는데.", "practiceQuestion": "Professor said the essay is due tonight, not Friday.", "practiceQuestionTranslation": "교수님이 에세이 마감 금요일 아니고 오늘 밤이래.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/924/practice-examples/ea384712-87bd-4fbc-a62c-e41e65e4b5bb.webp", "sentenceWords": ["Come", "again", "I", "haven''t", "even", "started"], "sentenceWordChoices": ["again", "haven''t", "even", "Come", "comes", "started", "I", "against", "start"]}, {"sentenceText": "Come again? You''re paying for everything?", "highlightingPart": "Come again", "sentenceTranslation": "다시 말해봐. 네가 전부 낸다고?", "practiceQuestion": "I''ll cover the whole trip if you plan it.", "practiceQuestionTranslation": "네가 계획 짜면 여행 경비 내가 다 낼게.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/924/practice-examples/92b3ac03-6343-448a-a2fc-2696d3b5a612.webp", "sentenceWords": ["Come", "again", "You''re", "paying", "for", "everything"], "sentenceWordChoices": ["against", "You''re", "pays", "everything", "comes", "paying", "again", "for", "Come"]}, {"sentenceText": "Come again? That was his dream company.", "highlightingPart": "Come again", "sentenceTranslation": "뭐라고? 거기 걔가 꿈꾸던 회사잖아.", "practiceQuestion": "He turned down the job offer.", "practiceQuestionTranslation": "걔 그 입사 제안 거절했대.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/expressions/924/practice-examples/ad707cb5-841d-40ee-9e76-e6529e9ac071.webp", "sentenceWords": ["Come", "again", "That", "was", "his", "dream", "company"], "sentenceWordChoices": ["were", "Come", "was", "comes", "again", "dream", "company", "That", "against", "his"]}]'::jsonb,'FREE_TALK','ACTIVE',now(),now(),'[-0.0202789307,0.00594329834,-0.0544128418,0.00590515137,0.0107955933,0.0204772949,0.00555419922,0.0419616699,-0.00294113159,0.0239105225,-0.0432739258,0.00367546082,0.00183773041,-0.00686645508,-0.0112838745,-0.00994873047,-0.0428466797,0.0122756958,0.00686645508,-0.00213623047,-0.0260467529,0.000942707062,-0.0487365723,0.0201263428,-0.00325584412,0.0182647705,-0.0215606689,0.0229187012,0.049621582,-0.0387878418,0.00198745728,-0.0303192139,-0.0151138306,-0.0101547241,0.00398635864,0.000457286835,0.0407104492,-0.00778198242,-0.0175628662,-0.0400390625,0.0164031982,-0.0240631104,0.0755615234,0.000252962112,0.0404052734,0.0353088379,0.00076007843,-0.00113105774,0.0291900635,0.049621582,-0.0136642456,0.0350341797,0.0133590698,0.112792969,-0.0294036865,-0.0320129395,0.040222168,0.0284576416,-0.00692749023,-0.0588989258,0.0357055664,-0.0491943359,0.00406265259,0.029800415,-0.00610733032,0.0267486572,0.0748291016,0.032409668,0.000636577606,0.00801849365,0.00169181824,-0.00291252136,-0.0438232422,0.0102615356,-0.001288414,0.00913238525,-0.0279083252,-0.0199584961,-4.66704369e-05,-0.0193023682,0.0197753906,-0.0142822266,0.00387954712,-